editManager::editManager(void) {
    m_viewX = 0;
    m_viewY = 0;
    m_cursorX = 0;
    m_cursorY = 0;
    m_window = NULL;
    gNextObjectLink = 1;
    m_zoomLevel = 0;
    gMap.Init(MAP_HEIGHT, MAP_WIDTH);
    gUndoMap.Init(MAP_HEIGHT, MAP_WIDTH);
    ResetArea(0, 0, MAP_WIDTH, MAP_HEIGHT);
    SaveUndo();
    m_animationFrame = 0;
    m_animationCounter = 0;
    m_tool = EDIT_TOOL_NONE;
    m_toolManager = NULL;
    m_mapChanged = false;
    m_placedX = m_placedY = EDIT_NO_CELL;
    m_extraCount = EDIT_MANAGER_FIRST_EXTRA;
    m_placedState = -1;
}

i32 editManager::Open(i32 priority) {
    i32 i;

    FillInOverlayTiles();
    InitializeMap(false, gNewMapSize, gNewMapSize);
    gpResourceManager->GetBackdrop("bordedit.icn", gpWindowManager->m_screen, true);
    m_window = new heroWindow(0, 0, "editwind.bin");
    m_horizontalTrack = new iconWidget(
        EDIT_TRACK_START,
        EDIT_TRACK_EDGE,
        EDIT_TRACK_LONG,
        EDIT_TRACK_SHORT,
        "escroll.icn",
        EDIT_SCROLL_HORIZONTAL_TRACK,
        ICON_DRAW_NORMAL,
        EDIT_CONTROL_HORIZONTAL_TRACK,
        WIDGET_KIND_ICON_DIRECT,
        1
    );
    m_verticalTrack = new iconWidget(
        EDIT_TRACK_EDGE,
        EDIT_TRACK_START,
        EDIT_TRACK_SHORT,
        EDIT_TRACK_LONG,
        "escroll.icn",
        EDIT_SCROLL_VERTICAL_TRACK,
        ICON_DRAW_NORMAL,
        EDIT_CONTROL_VERTICAL_TRACK,
        WIDGET_KIND_ICON_DIRECT,
        1
    );
    m_horizontalKnob = new iconWidget(
        EDIT_KNOB_START,
        EDIT_KNOB_EDGE,
        EDIT_KNOB_LONG,
        EDIT_KNOB_SHORT,
        "escroll.icn",
        EDIT_SCROLL_HORIZONTAL_KNOB,
        ICON_DRAW_NORMAL,
        EDIT_CONTROL_HORIZONTAL_KNOB,
        WIDGET_KIND_ICON_DIRECT,
        1
    );
    m_verticalKnob = new iconWidget(
        EDIT_KNOB_EDGE,
        EDIT_KNOB_START,
        EDIT_KNOB_SHORT,
        EDIT_KNOB_LONG,
        "escroll.icn",
        EDIT_SCROLL_VERTICAL_KNOB,
        ICON_DRAW_NORMAL,
        EDIT_CONTROL_VERTICAL_KNOB,
        WIDGET_KIND_ICON_DIRECT,
        1
    );
    m_window->AddWidget(m_horizontalTrack, -1);
    m_window->AddWidget(m_verticalTrack, -1);
    m_window->AddWidget(m_horizontalKnob, -1);
    m_window->AddWidget(m_verticalKnob, -1);
    gpWindowManager->AddWindow(m_window, -1, 1);
    m_groundTiles[0] = gpResourceManager->GetTileset("ground32.til");
    m_cloudTiles[0] = gpResourceManager->GetTileset("clof32.til");
    for (i = 0; i < EDIT_MANAGER_TILESET_COUNT; i++)
        m_objectIcons[i][0] = m_objectIcons[i][1] = NULL;
    for (i = 0; i < EDIT_MANAGER_TILESET_COUNT; i++) {
        if (strlen(gTilesetFiles[i]) > 1)
            m_objectIcons[i][0] = gpResourceManager->GetIcon(gTilesetFiles[i]);
    }
    m_buttons = gpResourceManager->GetIcon("editbtns.icn");
    m_radarIcons = gpResourceManager->GetIcon("radar.icn");
    m_window->DrawWindow(WINDOW_DRAW_BUFFER_ONLY);
    DrawRadar(true);
    DrawView(m_viewX, m_viewY);
    UpdateMapView();
    gpMouseManager->SetPointer("editor.mse", EDIT_POINTER_DEFAULT, MOUSE_AUTO_CURSOR_TYPE);
    gpMouseManager->ShowColorPointer();
    m_messageMask = BASE_MANAGER_ACCEPT_EXECUTIVE;
    m_priority = priority;
    m_active = true;
    strcpy(m_name, "editManager");
    SelectTool(EDIT_TOOL_TERRAIN);
    return 0;
}

void editManager::Close(void) {
    i32 i;

    InitializeMap(false, EDIT_DEFAULT_MAP_SIZE, EDIT_DEFAULT_MAP_SIZE);
    ClearErrors();
    SelectTool(EDIT_TOOL_NONE);
    gpWindowManager->RemoveWindow(m_window);
    delete m_window;
    m_window = NULL;
    gpResourceManager->Dispose(m_groundTiles[0]);
    gpResourceManager->Dispose(m_cloudTiles[0]);
    for (i = 0; i < EDIT_MANAGER_TILESET_COUNT; i++)
        gpResourceManager->Dispose(m_objectIcons[i][0]);
    gpResourceManager->Dispose(m_radarIcons);
    gpResourceManager->Dispose(m_buttons);
    gpMouseManager->SetPointer(-1);
    m_active = false;
}


i32 editManager::OverlayTypeAt(i32 x, i32 y) {
    b32 isLow;
    i32 sprite;
    i32 set;
    mapCellExtra* part;
    i32 i;
    i32 j;
    i32 found;
    mapCell* cell;

    found = OVERLAY_NONE;
    set = OVERLAY_NONE;
    sprite = OVERLAY_NONE;
    isLow = false;
    cell = gMap.CellAt(x, y);
    if (cell->m_overlayIndex != MAPCELL_SPRITE_NONE) {
        if (cell->m_overlayTileset != TILESET_FLAG32 && cell->m_overlayTileset != TILESET_EXTRAOVR) {
            set = H2EnumIndex(cell->m_overlayTileset);
            sprite = cell->m_overlayIndex;
        }
        if (cell->m_extraIndex
            && gMap.Extra(cell->m_extraIndex)->overlayIndex != MAPCELL_SPRITE_NONE)
            part = gMap.Extra(cell->m_extraIndex);
        else
            part = NULL;
        while (part) {
            if (part->overlayTileset != TILESET_FLAG32 && part->overlayTileset != TILESET_EXTRAOVR) {
                set = H2EnumIndex(part->overlayTileset);
                sprite = part->overlayIndex;
            }
            if (part->nextIndex && gMap.Extra(part->nextIndex)->overlayIndex != MAPCELL_SPRITE_NONE)
                part = gMap.Extra(part->nextIndex);
            else
                part = NULL;
        }
    } else if (cell->m_objectIndex != MAPCELL_SPRITE_NONE) {
        if (!cell->m_objectShadow && cell->m_objectTileset != TILESET_FLAG32
            && cell->m_objectTileset != TILESET_EXTRAOVR) {
            set = H2EnumIndex(cell->m_objectTileset);
            sprite = cell->m_objectIndex;
            isLow = cell->m_objectHighLayer;
        }
        if (cell->m_extraIndex
            && gMap.Extra(cell->m_extraIndex)->objectIndex != MAPCELL_SPRITE_NONE)
            part = gMap.Extra(cell->m_extraIndex);
        else
            part = NULL;
        while (part) {
            if ((!part->objectHighLayer || isLow) && !part->objectShadow
                && part->objectTileset != TILESET_FLAG32 && part->objectTileset != TILESET_EXTRAOVR) {
                set = H2EnumIndex(part->objectTileset);
                sprite = part->objectIndex;
                isLow = part->objectHighLayer;
            }
            if (part->nextIndex && gMap.Extra(part->nextIndex)->objectIndex != MAPCELL_SPRITE_NONE)
                part = gMap.Extra(part->nextIndex);
            else
                part = NULL;
        }
    }
    if (set == OVERLAY_NONE)
        return OVERLAY_NONE;
    for (i = 0; i < OVERLAY_TYPE_COUNT; i++) {
        if (gOverlayTypes[i].tileset != set)
            continue;
        for (j = 0; j < OVERLAY_GRID_CELLS; j++) {
            if (gOverlayTypes[i].frames[j] == sprite) {
                found = i;
                goto done;
            }
        }
    }
done:
    return found;
}


void editManager::GrabObject(void) {
    i32 x;
    i32 y;
    i32 index;

    index = OVERLAY_NONE;
    gpMouseManager->MouseCoords(x, y);
    ScreenToCell(x, y);
    x += m_viewX;
    y += m_viewY;
    index = OverlayTypeAt(x, y);
    if (index != OVERLAY_NONE) {
        gSelectedOverlay = OVERLAY_NONE;
        SelectTool(EDIT_TOOL_OBJECT);
        if (!static_cast<overlayManager*>(m_toolManager)->SelectOverlay(index))
            ShowStatusWarning(localization::Tr("editor.grab.failed"));
    } else {
        ShowStatusWarning(localization::Tr("editor.grab.nothing"));
    }
}


MessageDispatchResult editManager::Main(tag_message& message) {
    i32 mouseX;
    i32 mouseY;
    i32 amount;
    fullMap* temp;
    tag_message move;
    i32 hint;
    i32 choice;
    i32 objectKind;
    i32 newMap;
    i32 mapX;
    i32 cellEvent;
    i32 mapY;
    i32 iconIndex;
    TilesetId tilesetId;
    i32 kindIndex;
    mapCell* cell;
    char initial;

    hint = EDIT_PANEL_HELP_NONE;
    if (giScreenScroll && gbForegroundApp)
        CheckScreenScroll();
    if (gConfig.editorScreenAnimation && gLastAnimationTick + EDIT_ANIMATION_TICKS < KBTickCount()
        && message.type == MESSAGE_NONE) {
        m_animationCounter++;
        m_animationFrame++;
        m_animationFrame %= EDIT_ANIMATION_FRAMES;
        DrawMap();
        gEditManager->m_cursorX = EDIT_NO_CELL;
        memset(&move, 0, sizeof(move));
        move.type = MESSAGE_MOUSE_MOVE;
        gpMouseManager->MouseCoords(mouseX, mouseY);
        move.payload.mouse.screenX = move.payload.mouse.x = mouseX;
        move.payload.mouse.screenY = move.payload.mouse.y = mouseY;
        m_toolManager->Main(move);
        UpdateMapView();
        return MESSAGE_DISPATCH_CONTINUE;
    }
    switch (message.type) {
        case MESSAGE_NONE:
            if (gNewRandomMap) {
                GenerateRandomMap();
                gNewRandomMap = false;
            }
            break;
        case MESSAGE_WIDGET:
            switch (message.payload.widget.command) {
                case WIDGET_NOTIFY_DESELECT:
                    if ((H2EnumIndex((message.payload.widget.modifiers) & (MESSAGE_MODIFIER_RIGHT_BUTTON))))
                        break;
                    switch (message.payload.widget.id) {
                        case EDIT_CONTROL_TERRAIN:
                            SelectTool(EDIT_TOOL_TERRAIN);
                            break;
                        case EDIT_CONTROL_OBJECT:
                            SelectTool(EDIT_TOOL_OBJECT);
                            break;
                        case EDIT_CONTROL_DETAIL:
                            SelectTool(EDIT_TOOL_DETAIL);
                            break;
                        case EDIT_CONTROL_ERASE:
                            SelectTool(EDIT_TOOL_ERASE);
                            break;
                        case EDIT_CONTROL_STREAM:
                            SelectTool(EDIT_TOOL_STREAM);
                            break;
                        case EDIT_CONTROL_ROAD:
                            SelectTool(EDIT_TOOL_ROAD);
                            break;
                        case EDIT_CONTROL_SPECIFICATIONS:
                            EditMapSpecifications(false);
                            break;
                        case EDIT_CONTROL_ZOOM:
                            ToggleZoom();
                            break;
                        case EDIT_CONTROL_LOAD:
                        confirmLoad:
                            if (!Confirm(localization::Tr("editor.map.load.confirm")))
                                break;
                        load:
                            if (!PickMap(FILE_REQUESTER_MAP))
                                break;
                            if (!LoadMap(gMapFileName)) {
                                ProtectShippedMap();
                                m_mapChanged = false;
                                m_placedX = m_placedY = EDIT_NO_CELL;
                            }
                            m_viewX = m_viewY = 0;
                            m_window->DrawWindow(WINDOW_DRAW_BUFFER_ONLY);
                            DrawRadar(true);
                            DrawMap();
                            UpdateMapView();
                            break;
                        case EDIT_CONTROL_SAVE:
                        save:
                            if (!SaveMap(gMapFileName)) {
                                sprintf(gText, localization::Tr("editor.map.saved"), gEditMapHeader.name);
                                if (UsesExpansionObjects())
                                    strcat(gText, localization::Tr("editor.map.saved.expansion"));
                                else
                                    strcat(gText, localization::Tr("editor.map.saved.original"));
                                NormalDialog(gText, NORMAL_DIALOG_INFO);
                                m_mapChanged = false;
                                m_placedX = m_placedY = EDIT_NO_CELL;
                            }
                            break;
                        case EDIT_CONTROL_QUIT:
                        confirmQuit:
                            if (Confirm(localization::Tr("editor.quit.confirm")) == true) {
                            quit:
                                gpWindowManager->FadeScreen(FADE_OUT, FADE_SPEED_FINE, gPalette);
                                ShutDown(NULL);
                            } else {
                                return MESSAGE_DISPATCH_CONSUME;
                            }
                            break;
                        case EDIT_CONTROL_FILE:
                            choice = FileOptions();
                            if (choice == EDIT_FILE_MENU_LOAD)
                                goto load;
                            if (choice == EDIT_FILE_MENU_NEW)
                                goto startNewMap;
                            if (choice == EDIT_FILE_MENU_SAVE)
                                goto save;
                            if (choice == EDIT_FILE_MENU_QUIT)
                                goto quit;
                            break;
                        case EDIT_CONTROL_NEW:
                        startNewMap:
                            gpWindowManager->FadeScreen(FADE_OUT, FADE_SPEED_STANDARD, gPalette);
                            gpResourceManager->GetBackdrop("editor.icn", gpWindowManager->m_screen,
                                                           true);
                            gpWindowManager->UpdateScreen();
                            gpWindowManager->FadeScreen(FADE_IN, FADE_SPEED_STANDARD, gPalette);
                            newMap = SetupNewMap();
                            gpWindowManager->FadeScreen(FADE_OUT, FADE_SPEED_STANDARD, gPalette);
                            memset(gpWindowManager->m_screen->m_pixels, SCREEN_FILL_COLOR,
                                   LOGICAL_SCREEN_WIDTH * LOGICAL_SCREEN_HEIGHT);
                            if (newMap) {
                                gEditManager->InitializeMap(false, gNewMapSize, gNewMapSize);
                                ResetArea(0, 0, MAP_WIDTH, MAP_HEIGHT);
                            }
                            gpResourceManager->GetBackdrop("bordedit.icn", gpWindowManager->m_screen,
                                                           true);
                            m_window->DrawWindow(WINDOW_DRAW_BUFFER_ONLY);
                            DrawMap();
                            DrawRadar(true);
                            gpWindowManager->UpdateScreen();
                            gpWindowManager->FadeScreen(FADE_IN, FADE_SPEED_STANDARD, gPalette);
                            break;
                        case EDIT_CONTROL_SYSTEM:
                            SystemOptions();
                            break;
                        case EDIT_CONTROL_UNDO:
                            temp = new fullMap;
                            temp->Init(MAP_WIDTH, MAP_HEIGHT);
                            temp->Copy(gMap);
                            gMap.Copy(gUndoMap);
                            gUndoMap.Copy(*temp);
                            delete temp;
                            DrawView(m_viewX, m_viewY);
                            UpdateMapView();
                            DrawRadar(true);
                            break;
                        case EDIT_CONTROL_SCROLL_UP:
                            Scroll(0, -1);
                            break;
                        case EDIT_CONTROL_SCROLL_DOWN:
                            Scroll(0, 1);
                            break;
                        case EDIT_CONTROL_SCROLL_RIGHT:
                            Scroll(1, 0);
                            break;
                        case EDIT_CONTROL_SCROLL_LEFT:
                            Scroll(-1, 0);
                            break;
                        case EDIT_CONTROL_SCROLL_UP_LEFT:
                            Scroll(-1, -1);
                            break;
                        case EDIT_CONTROL_SCROLL_UP_RIGHT:
                            Scroll(1, -1);
                            break;
                        case EDIT_CONTROL_SCROLL_DOWN_LEFT:
                            Scroll(-1, 1);
                            break;
                        case EDIT_CONTROL_SCROLL_DOWN_RIGHT:
                            Scroll(1, 1);
                            break;
                    }
                    break;
                case WIDGET_NOTIFY_SELECT:
                case WIDGET_NOTIFY_RIGHT_CLICK:
                    if ((H2EnumIndex((message.payload.widget.modifiers) & (MESSAGE_MODIFIER_RIGHT_BUTTON)))) {
                        switch (message.payload.widget.id) {
                            case EDIT_CONTROL_RADAR:
                                hint = EDIT_PANEL_HELP_RADAR;
                                break;
                            case EDIT_CONTROL_HORIZONTAL_TRACK:
                                hint = EDIT_PANEL_HELP_SCROLL_BARS;
                                break;
                            case EDIT_CONTROL_HORIZONTAL_KNOB:
                                hint = EDIT_PANEL_HELP_SCROLL_BARS;
                                break;
                            case EDIT_CONTROL_VERTICAL_TRACK:
                                hint = EDIT_PANEL_HELP_SCROLL_BARS;
                                break;
                            case EDIT_CONTROL_VERTICAL_KNOB:
                                hint = EDIT_PANEL_HELP_SCROLL_BARS;
                                break;
                            case EDIT_CONTROL_TERRAIN:
                                hint = EDIT_PANEL_HELP_TERRAIN;
                                break;
                            case EDIT_CONTROL_OBJECT:
                                hint = EDIT_PANEL_HELP_OBJECT;
                                break;
                            case EDIT_CONTROL_DETAIL:
                                hint = EDIT_PANEL_HELP_DETAIL;
                                break;
                            case EDIT_CONTROL_ERASE:
                                hint = EDIT_PANEL_HELP_ERASE;
                                break;
                            case EDIT_CONTROL_STREAM:
                                hint = EDIT_PANEL_HELP_STREAM;
                                break;
                            case EDIT_CONTROL_ROAD:
                                hint = EDIT_PANEL_HELP_ROAD;
                                break;
                            case EDIT_CONTROL_SCROLL_UP:
                                hint = EDIT_PANEL_HELP_SCROLL_ARROWS;
                                break;
                            case EDIT_CONTROL_SCROLL_DOWN:
                                hint = EDIT_PANEL_HELP_SCROLL_ARROWS;
                                break;
                            case EDIT_CONTROL_SCROLL_RIGHT:
                                hint = EDIT_PANEL_HELP_SCROLL_ARROWS;
                                break;
                            case EDIT_CONTROL_SCROLL_LEFT:
                                hint = EDIT_PANEL_HELP_SCROLL_ARROWS;
                                break;
                            case EDIT_CONTROL_SCROLL_UP_LEFT:
                                hint = EDIT_PANEL_HELP_SCROLL_ARROWS;
                                break;
                            case EDIT_CONTROL_SCROLL_UP_RIGHT:
                                hint = EDIT_PANEL_HELP_SCROLL_ARROWS;
                                break;
                            case EDIT_CONTROL_SCROLL_DOWN_LEFT:
                                hint = EDIT_PANEL_HELP_SCROLL_ARROWS;
                                break;
                            case EDIT_CONTROL_SCROLL_DOWN_RIGHT:
                                hint = EDIT_PANEL_HELP_SCROLL_ARROWS;
                                break;
                            case EDIT_CONTROL_ZOOM:
                                hint = EDIT_PANEL_HELP_ZOOM;
                                break;
                            case EDIT_CONTROL_UNDO:
                                hint = EDIT_PANEL_HELP_UNDO;
                                break;
                            case EDIT_CONTROL_SPECIFICATIONS:
                                hint = EDIT_PANEL_HELP_SPECIFICATIONS;
                                break;
                            case EDIT_CONTROL_NEW:
                                hint = EDIT_PANEL_HELP_NEW;
                                break;
                            case EDIT_CONTROL_FILE:
                                hint = EDIT_PANEL_HELP_FILE;
                                break;
                            case EDIT_CONTROL_SYSTEM:
                                hint = EDIT_PANEL_HELP_SYSTEM;
                                break;
                        }
                        if (message.payload.widget.id == EDIT_CONTROL_MAP) {
                            mapX = message.payload.widget.screenX;
                            mapY = message.payload.widget.screenY;
                            ScreenToCell(mapX, mapY);
                            mapX += gEditManager->m_viewX;
                            mapY += gEditManager->m_viewY;
                            objectKind = OverlayTypeAt(mapX, mapY);
                            cellEvent = OVERLAY_NONE;
                            if (objectKind != OVERLAY_NONE)
                                cellEvent = gOverlayTypes[objectKind].trigger;
                            if (cellEvent == OVERLAY_NONE || cellEvent == H2EnumIndex(MAP_OBJECT_NOTHING_SPECIAL)
                                || cellEvent == H2EnumIndex(MAP_OBJECT_MOSSY_ROCK)) {
                                sprintf(gText,
                                        gTerrainNames[H2EnumIndex(giGroundToTerrain[gMap.CellAt(mapX, mapY)
                                                                            ->m_terrainImageIndex])]);
                            } else {
                                cell = gMap.CellAt(mapX, mapY);
                                switch (cellEvent) {
                                    case H2EnumIndex(MAP_OBJECT_BARRIER):
                                    case H2EnumIndex(MAP_OBJECT_TRAVELER_TENT):
                                        sprintf(gText,
                                                gQuickViewText[H2EnumIndex(MAP_TRIGGER_OBJECT(cell->m_triggerType))],
                                                xBarrierColor[cell->m_objectMetadata
                                                              & EDIT_BARRIER_COLOR_MASK]);
                                        initial = toupper(static_cast<i32>(gText[0]));
                                        gText[0] = initial;
                                        break;
                                    case H2EnumIndex(MAP_OBJECT_EXPANSION_OBJECT):
                                        if (cell->m_overlayIndex == MAPCELL_SPRITE_NONE) {
                                            iconIndex = cell->m_objectIndex;
                                            tilesetId = cell->m_objectTileset;
                                        } else {
                                            iconIndex = cell->m_overlayIndex;
                                            tilesetId = cell->m_overlayTileset;
                                        }
                                        kindIndex = H2EnumIndex(GENERIC_SITE_UNKNOWN);
                                        switch (tilesetId) {
                                            case TILESET_X_LOC1:
                                                if (iconIndex < 0)
                                                    break;
                                                if (iconIndex < EDIT_X_LOC1_ALCHEMIST_TOWER_END)
                                                    kindIndex = H2EnumIndex(GENERIC_SITE_ALCHEMIST_TOWER);
                                                else if (iconIndex < EDIT_X_LOC1_ARENA_END)
                                                    kindIndex = H2EnumIndex(GENERIC_SITE_ARENA);
                                                break;
                                            case TILESET_X_LOC2:
                                                if (iconIndex < 0)
                                                    break;
                                                if (iconIndex < EDIT_X_LOC2_STABLES_END)
                                                    kindIndex = H2EnumIndex(GENERIC_SITE_STABLES);
                                                else if (iconIndex < EDIT_X_LOC2_STRAY_END)
                                                    kindIndex = EDIT_SITE_NAME_STRAY;
                                                else if (iconIndex < EDIT_X_LOC2_MERMAID_END)
                                                    kindIndex = H2EnumIndex(GENERIC_SITE_MERMAID);
                                                else if (iconIndex < EDIT_X_LOC2_SIRENS_END)
                                                    kindIndex = H2EnumIndex(GENERIC_SITE_SIRENS);
                                                break;
                                            case TILESET_X_LOC3:
                                                if (iconIndex < 0)
                                                    break;
                                                if (iconIndex < EDIT_X_LOC3_HUT_OF_MAGI_END)
                                                    kindIndex = H2EnumIndex(GENERIC_SITE_HUT_OF_MAGI);
                                                else if (iconIndex < EDIT_X_LOC3_EYE_OF_MAGI_END)
                                                    kindIndex = H2EnumIndex(GENERIC_SITE_EYE_OF_MAGI);
                                                break;
                                        }
                                        if (kindIndex == H2EnumIndex(GENERIC_SITE_UNKNOWN))
                                            sprintf(gText, localization::Tr("editor.quick_view.unknown"));
                                        else
                                            sprintf(gText, xGenericSiteNames[kindIndex]);
                                        break;
                                    case H2EnumIndex(MAP_OBJECT_EXPANSION_DWELLING):
                                        if (cell->m_overlayIndex == MAPCELL_SPRITE_NONE) {
                                            iconIndex = cell->m_objectIndex;
                                            tilesetId = cell->m_objectTileset;
                                        } else {
                                            iconIndex = cell->m_overlayIndex;
                                            tilesetId = cell->m_overlayTileset;
                                        }
                                        kindIndex = H2EnumIndex(GENERIC_SITE_UNKNOWN);
                                        switch (tilesetId) {
                                            case TILESET_X_LOC1:
                                                if (iconIndex < EDIT_X_LOC1_ARENA_END)
                                                    break;
                                                if (iconIndex < EDIT_X_LOC1_DWELLING_1_END)
                                                    kindIndex = H2EnumIndex(RECRUITMENT_SITE_BARROW_MOUNDS);
                                                else if (iconIndex < EDIT_X_LOC1_DWELLING_2_END)
                                                    kindIndex = H2EnumIndex(RECRUITMENT_SITE_EARTH_ALTAR);
                                                else if (iconIndex < EDIT_X_LOC1_DWELLING_3_END)
                                                    kindIndex = H2EnumIndex(RECRUITMENT_SITE_AIR_ALTAR);
                                                else if (iconIndex < EDIT_X_LOC1_DWELLING_4_END)
                                                    kindIndex = H2EnumIndex(RECRUITMENT_SITE_FIRE_ALTAR);
                                                else if (iconIndex < EDIT_X_LOC1_DWELLING_5_END)
                                                    kindIndex = H2EnumIndex(RECRUITMENT_SITE_WATER_ALTAR);
                                                break;
                                        }
                                        if (kindIndex == H2EnumIndex(GENERIC_SITE_UNKNOWN))
                                            sprintf(gText, localization::Tr("editor.quick_view.unknown"));
                                        else
                                            sprintf(gText, xRecruitmentSiteNames[kindIndex]);
                                        break;
                                    case H2EnumIndex(MAP_OBJECT_ROCK):
                                        if (cell->m_objectTileset == TILESET_X_LOC2)
                                            sprintf(gText, localization::Tr("editor.quick_view.reefs"));
                                        else
                                            sprintf(gText, localization::Tr("editor.quick_view.rocks"));
                                        break;
                                    default:
                                        sprintf(gText, gQuickViewText[cellEvent]);
                                        break;
                                }
                            }
                            NormalDialog(gText, NORMAL_DIALOG_QUICK_VIEW);
                        } else if (hint >= 0) {
                            NormalDialog(gEditPanelHelp[hint], NORMAL_DIALOG_QUICK_VIEW);
                        }
                    } else {
                        switch (message.payload.widget.id) {
                            case EDIT_CONTROL_RADAR:
                                DoRadar();
                                break;
                            case EDIT_CONTROL_HORIZONTAL_TRACK:
                            case EDIT_CONTROL_HORIZONTAL_KNOB:
                                DoHorizontalKnob();
                                break;
                            case EDIT_CONTROL_VERTICAL_TRACK:
                            case EDIT_CONTROL_VERTICAL_KNOB:
                                DoVerticalKnob();
                                break;
                        }
                    }
                    break;
            }
            return MESSAGE_DISPATCH_CONTINUE;
        case MESSAGE_KEY_DOWN:
            switch (message.payload.keyboard.keyCode) {
                case INPUT_SCAN_Q:
                    goto confirmQuit;
                case INPUT_SCAN_S:
                    goto save;
                case INPUT_SCAN_L:
                    goto confirmLoad;
                case INPUT_SCAN_G:
                    GrabObject();
                    break;
                case INPUT_SCAN_T:
                    if ((H2EnumIndex((message.payload.keyboard.modifiers) & (MESSAGE_MODIFIER_SHIFT_KEYS))))
                        ExportMapText();
                    else
                        ToggleGroundVariant();
                    break;
                case INPUT_SCAN_R:
                    if ((H2EnumIndex((message.payload.keyboard.modifiers) & (MESSAGE_MODIFIER_SHIFT_KEYS)))
                        && !ImportMapText())
                        NormalDialog(localization::Tr("editor.text.import_failed"), NORMAL_DIALOG_INFO);
                    break;
                case INPUT_SCAN_0:
                    amount = 0;
                    goto randomize;
                case INPUT_SCAN_1:
                    amount = 1;
                    goto randomize;
                case INPUT_SCAN_2:
                    amount = 2;
                    goto randomize;
                case INPUT_SCAN_3:
                    amount = 3;
                    goto randomize;
                case INPUT_SCAN_4:
                    amount = 4;
                    goto randomize;
                case INPUT_SCAN_5:
                    amount = 5;
                    goto randomize;
                case INPUT_SCAN_6:
                    amount = 6;
                    goto randomize;
                case INPUT_SCAN_7:
                    amount = 7;
                    goto randomize;
                case INPUT_SCAN_8:
                    amount = 8;
                    goto randomize;
                case INPUT_SCAN_9:
                    amount = 9;
                randomize:
                    if ((H2EnumIndex((message.payload.keyboard.modifiers) & (MESSAGE_MODIFIER_CONTROL_KEYS))))
                        RandomizeGround(amount);
                    break;
                case INPUT_SCAN_TAB:
                    SelectTool((m_tool + 1) % EDIT_TOOL_COUNT);
                    break;
                case INPUT_SCAN_ESCAPE:
                    if (Confirm(localization::Tr("editor.quit.confirm")) == true)
                        ShutDown(NULL);
                    else
                        return MESSAGE_DISPATCH_CONSUME;
                    break;
            }
            break;
    }
    return MESSAGE_DISPATCH_CONTINUE;
}

void editManager::SaveUndo(void) {
    gUndoMap.Copy(gMap);
}

void editManager::UpdateMapView(void) {
    gpWindowManager->UpdateScreenRegion(EDIT_VIEW_LEFT, EDIT_VIEW_TOP, EDIT_VIEW_PIXELS, EDIT_VIEW_PIXELS);
}

void editManager::UpdateCursor(void) {
    DrawRulers(m_viewX, m_viewY, m_cursorX, m_cursorY);
}

void editManager::DrawRulers(i32 viewX, i32 viewY, i32 cursorX, i32 cursorY) {
    i32 mouseX;
    i32 mouseY;
    u8 color;
    char text[EDIT_RULER_TEXT_SIZE];
    i32 i;
    i32 cell;

    gpMouseManager->MouseCoords(mouseX, mouseY);
    cursorX -= m_viewX;
    cursorY -= m_viewY;
    if (m_zoomLevel == EDIT_ZOOM_FAR) {
        cursorX &= EDIT_RULER_EVEN_CELL_MASK;
        cursorY &= EDIT_RULER_EVEN_CELL_MASK;
    }
    if (mouseX < EDIT_VIEW_LEFT || mouseX >= EDIT_VIEW_RIGHT
        || mouseY < EDIT_VIEW_TOP || mouseY > EDIT_VIEW_BOTTOM) {
        cursorX = EDIT_NO_CELL;
        cursorY = EDIT_NO_CELL;
    }
    for (i = 0; i < EDIT_RULER_SLOTS; i++) {
        if (m_zoomLevel == EDIT_ZOOM_NORMAL && (i & 1))
            continue;
        if (m_zoomLevel == EDIT_ZOOM_NORMAL)
            m_buttons->DrawToBuffer(
                i * EDIT_RULER_SLOT_PIXELS + EDIT_VIEW_LEFT, 0, EDIT_FRAME_TOP_RULER_CELL,
                ICON_DRAW_NORMAL
            );
        else
            m_buttons->DrawToBuffer(
                i * EDIT_RULER_SLOT_PIXELS + EDIT_VIEW_LEFT, 0, EDIT_FRAME_ZOOMED_RULER_CELL,
                ICON_DRAW_NORMAL
            );
        if (m_zoomLevel == EDIT_ZOOM_NORMAL)
            cell = i / EDIT_RULER_ZOOM_STEP;
        else if (m_zoomLevel == EDIT_ZOOM_HALF)
            cell = i;
        else
            cell = i * EDIT_RULER_ZOOM_STEP;
        sprintf(text, "%02d", viewX + cell);
        if (cell == cursorX)
            sprintf(text, "%02d", viewX + cell);
        else
            sprintf(text, "{%02d}", viewX + cell);
        color = H2EnumIndex(FONT_DRAW_DEFAULT);
        smallFont->DrawString(
            text,
            i * EDIT_RULER_SLOT_PIXELS + (m_zoomLevel ? 0 : EDIT_RULER_CELL_TEXT_OFFSET)
                + EDIT_TOP_RULER_TEXT_X,
            EDIT_TOP_RULER_TEXT_Y,
            static_cast<FontDrawMode>(color)
        );
        if (m_zoomLevel == EDIT_ZOOM_NORMAL)
            m_buttons->DrawToBuffer(
                0, i * EDIT_RULER_SLOT_PIXELS + EDIT_VIEW_TOP, EDIT_FRAME_LEFT_RULER_CELL,
                ICON_DRAW_NORMAL
            );
        else
            m_buttons->DrawToBuffer(
                0, i * EDIT_RULER_SLOT_PIXELS + EDIT_VIEW_TOP, EDIT_FRAME_ZOOMED_RULER_CELL,
                ICON_DRAW_NORMAL
            );
        if (cell == cursorY)
            sprintf(text, "%02d", viewY + cell);
        else
            sprintf(text, "{%02d}", viewY + cell);
        color = H2EnumIndex(FONT_DRAW_DEFAULT);
        smallFont->DrawString(
            text,
            EDIT_LEFT_RULER_TEXT_X,
            i * EDIT_RULER_SLOT_PIXELS + (m_zoomLevel ? 0 : EDIT_RULER_CELL_TEXT_OFFSET)
                + EDIT_LEFT_RULER_TEXT_Y,
            static_cast<FontDrawMode>(color)
        );
    }
    gpWindowManager->UpdateScreenRegion(EDIT_VIEW_LEFT, 0, EDIT_VIEW_PIXELS, EDIT_VIEW_TOP);
    gpWindowManager->UpdateScreenRegion(0, EDIT_VIEW_TOP, EDIT_VIEW_LEFT, EDIT_VIEW_PIXELS);
}

void editManager::ScreenToCell(i32& x, i32& y) {
    x -= EDIT_VIEW_LEFT;
    y -= EDIT_VIEW_TOP;
    x /= gZoomTileSize[m_zoomLevel];
    if (x < 0)
        x = 0;
    if (x > gZoomViewCells[m_zoomLevel] - 1)
        x = gZoomViewCells[m_zoomLevel] - 1;
    y /= gZoomTileSize[m_zoomLevel];
    if (y < 0)
        y = 0;
    if (y > gZoomViewCells[m_zoomLevel] - 1)
        y = gZoomViewCells[m_zoomLevel] - 1;
}

void editManager::DrawMap(void) {
    DrawView(m_viewX, m_viewY);
}

void editManager::DrawView(i32 viewX, i32 viewY) {
    i32 col;
    i32 outline;
    i32 tileSize;
    i32 row;
    i32 cells;
    i32 oldZoom;

    oldZoom = m_zoomLevel;
    if (gGeneratingMap)
        m_zoomLevel = EDIT_ZOOM_NORMAL;
    cells = gZoomViewCells[m_zoomLevel];
    for (row = 0; row < cells; row++)
        for (col = 0; col < cells; col++)
            DrawCell(viewX + col, viewY + row, col, row, EDIT_DRAW_GROUND);
    for (row = 0; row < cells; row++) {
        for (col = 0; col < cells; col++)
            DrawCell(viewX + col, viewY + row, col, row, EDIT_DRAW_OBJECTS);
        if (row > 0) {
            for (col = 0; col < cells; col++)
                DrawCell(viewX + col, viewY + row - 1, col, row - 1, EDIT_DRAW_OVERHANGING);
        }
    }
    for (col = 0; col < cells; col++)
        DrawCell(viewX + col, viewY + cells - 1, col, cells - 1, EDIT_DRAW_OVERHANGING);
    gLastAnimationTick = KBTickCount();
    if (!gConfig.editorScreenAnimation) {
        m_animationCounter++;
        m_animationFrame++;
        m_animationFrame %= EDIT_ANIMATION_FRAMES;
    }
    tileSize = gZoomTileSize[m_zoomLevel];
    outline = m_zoomLevel ? EDIT_SELECTION_LINE_ZOOMED : EDIT_SELECTION_LINE_NORMAL;
    if (gSelectionX >= 0) {
        gSelectionColor = EDIT_SELECTION_COLOR;
        FillBitmapAreaClip(
            gpWindowManager->m_screen,
            (gSelectionX - viewX) * tileSize + EDIT_VIEW_LEFT,
            (gSelectionY - viewY) * tileSize + EDIT_VIEW_TOP,
            outline,
            gSelectionHeight * tileSize - 1,
            gSelectionColor,
            EDIT_VIEW_LEFT,
            EDIT_VIEW_TOP,
            EDIT_VIEW_PIXELS,
            EDIT_VIEW_PIXELS
        );
        FillBitmapAreaClip(
            gpWindowManager->m_screen,
            (gSelectionX - viewX) * tileSize + EDIT_VIEW_LEFT,
            (gSelectionY - viewY) * tileSize + EDIT_VIEW_TOP,
            gSelectionWidth * tileSize - 1,
            outline,
            gSelectionColor,
            EDIT_VIEW_LEFT,
            EDIT_VIEW_TOP,
            EDIT_VIEW_PIXELS,
            EDIT_VIEW_PIXELS
        );
        FillBitmapAreaClip(
            gpWindowManager->m_screen,
            (gSelectionX - viewX + gSelectionWidth) * tileSize + EDIT_VIEW_LEFT - outline,
            (gSelectionY - viewY) * tileSize + EDIT_VIEW_TOP,
            outline,
            gSelectionHeight * tileSize - 1,
            gSelectionColor,
            EDIT_VIEW_LEFT,
            EDIT_VIEW_TOP,
            EDIT_VIEW_PIXELS,
            EDIT_VIEW_PIXELS
        );
        FillBitmapAreaClip(
            gpWindowManager->m_screen,
            (gSelectionX - viewX) * tileSize + EDIT_VIEW_LEFT,
            (gSelectionY - viewY + gSelectionHeight) * tileSize + EDIT_VIEW_TOP - outline,
            gSelectionWidth * tileSize - 1,
            outline,
            gSelectionColor,
            EDIT_VIEW_LEFT,
            EDIT_VIEW_TOP,
            EDIT_VIEW_PIXELS,
            EDIT_VIEW_PIXELS
        );
    }
    m_zoomLevel = oldZoom;
}

void editManager::DrawRadar(b32 updateScreen [[maybe_unused]]) {
    u8* line;
    i32 rowPhase;
    u8 color;
    i32 xPhase;
    i32 radarX;
    i32 x;
    i32 radarY;
    u8* dst;
    i32 frame;
    i32 unusedA [[maybe_unused]];
    i32 unusedB [[maybe_unused]];
    i32 mapY;
    mapCell* cell;
    i32 tile;

    line = gpWindowManager->m_screen->m_pixels + EDIT_RADAR_OFFSET;
    dst = line;
    xPhase = rowPhase = 0;
    for (mapY = 0; mapY < MAP_HEIGHT; mapY++) {
        dst = line;
        switch (MAP_HEIGHT) {
            case MAP_DIMENSION_SMALL:
                line += H2EnumIndex(ADVENTURE_RADAR_SMALL_CELL_PIXELS) * EDIT_SCREEN_PITCH;
                break;
            case MAP_DIMENSION_MEDIUM:
                line += H2EnumIndex(ADVENTURE_RADAR_MEDIUM_CELL_PIXELS) * EDIT_SCREEN_PITCH;
                break;
            case MAP_DIMENSION_LARGE:
                rowPhase++;
                if (rowPhase > ADVENTURE_RADAR_LARGE_SCALE_DIVISOR - 1)
                    rowPhase = 0;
                if (rowPhase)
                    line += EDIT_SCREEN_PITCH;
                else
                    line += EDIT_RADAR_LARGE_WIDE_DOT * EDIT_SCREEN_PITCH;
                break;
            case MAP_DIMENSION_XLARGE:
                line += EDIT_SCREEN_PITCH;
                break;
        }
        for (x = 0; x < MAP_WIDTH; x++) {
            cell = &gMap.Column(x)[mapY * gMap.width];
            tile = -1;
            if (cell->m_objectIndex != MAPCELL_SPRITE_NONE)
                tile = H2EnumIndex(cell->m_objectTileset);
            else if (cell->m_overlayIndex != MAPCELL_SPRITE_NONE)
                tile = H2EnumIndex(cell->m_overlayTileset);
            switch (tile) {
                case H2EnumIndex(TILESET_MTNSNOW):
                case H2EnumIndex(TILESET_MTNSWMP):
                case H2EnumIndex(TILESET_MTNLAVA):
                case H2EnumIndex(TILESET_MTNDSRT):
                case H2EnumIndex(TILESET_MTNDIRT):
                case H2EnumIndex(TILESET_MTNMULT):
                case H2EnumIndex(TILESET_MTNCRCK):
                case H2EnumIndex(TILESET_MTNGRAS):
                case H2EnumIndex(TILESET_TREJNGL):
                case H2EnumIndex(TILESET_TREEVIL):
                case H2EnumIndex(TILESET_TRESNOW):
                case H2EnumIndex(TILESET_TREFIR):
                case H2EnumIndex(TILESET_TREFALL):
                case H2EnumIndex(TILESET_TREDECI):
                    switch (cell->m_triggerType) {
                        case H2EnumIndex(MAP_OBJECT_ALCHEMIST_LAB):
                        case H2EnumIndex(MAP_OBJECT_MINE):
                        case H2EnumIndex(MAP_OBJECT_SAWMILL):
                        case MAP_ACTION_TRIGGER(MAP_OBJECT_ALCHEMIST_LAB):
                        case MAP_ACTION_TRIGGER(MAP_OBJECT_MINE):
                        case MAP_ACTION_TRIGGER(MAP_OBJECT_SAWMILL):
                            color = EDIT_RADAR_TOWN_COLOR;
                            break;
                        default:
                            color = gMapColors[H2EnumIndex(giGroundToTerrain[gMap.Column(x)[mapY * gMap.width].m_terrainImageIndex])]
                                    + EDIT_RADAR_OBSTACLE_SHADE;
                            break;
                    }
                    break;
                case H2EnumIndex(TILESET_OBJNTOWN):
                case H2EnumIndex(TILESET_OBJNTWBA):
                    color = EDIT_RADAR_TOWN_COLOR;
                    break;
                default:
                    color = gMapColors[H2EnumIndex(giGroundToTerrain[gMap.Column(x)[mapY * gMap.width].m_terrainImageIndex])];
                    break;
            }
            if (gGeneratingMap)
                color = EDIT_RADAR_UNSEEN_COLOR;
            switch (MAP_HEIGHT) {
                case MAP_DIMENSION_SMALL:
                    memset(dst, color, ADVENTURE_RADAR_SMALL_CELL_PIXELS);
                    memset(dst + EDIT_SCREEN_PITCH, color, ADVENTURE_RADAR_SMALL_CELL_PIXELS);
                    memset(dst + 2 * EDIT_SCREEN_PITCH, color, ADVENTURE_RADAR_SMALL_CELL_PIXELS);
                    memset(dst + 3 * EDIT_SCREEN_PITCH, color, ADVENTURE_RADAR_SMALL_CELL_PIXELS);
                    dst += ADVENTURE_RADAR_SMALL_CELL_PIXELS;
                    break;
                case MAP_DIMENSION_MEDIUM:
                    memset(dst, color, ADVENTURE_RADAR_MEDIUM_CELL_PIXELS);
                    memset(dst + EDIT_SCREEN_PITCH, color, ADVENTURE_RADAR_MEDIUM_CELL_PIXELS);
                    dst += ADVENTURE_RADAR_MEDIUM_CELL_PIXELS;
                    break;
                case MAP_DIMENSION_LARGE:
                    if (xPhase) {
                        if (rowPhase) {
                            *dst = color;
                            dst++;
                        } else {
                            *dst = color;
                            dst[EDIT_SCREEN_PITCH] = color;
                            dst++;
                        }
                    } else if (rowPhase) {
                        dst[0] = color;
                        dst[1] = color;
                        dst += EDIT_RADAR_LARGE_WIDE_DOT;
                    } else {
                        dst[0] = color;
                        dst[1] = color;
                        dst[EDIT_SCREEN_PITCH] = color;
                        dst[EDIT_SCREEN_PITCH + 1] = color;
                        dst += EDIT_RADAR_LARGE_WIDE_DOT;
                    }
                    xPhase++;
                    if (xPhase > ADVENTURE_RADAR_LARGE_SCALE_DIVISOR - 1)
                        xPhase = 0;
                    break;
                case MAP_DIMENSION_XLARGE:
                    *dst = color;
                    dst++;
                    break;
            }
        }
    }
    frame = -1;
    switch (MAP_HEIGHT) {
        case MAP_DIMENSION_SMALL:
            switch (m_zoomLevel) {
                case EDIT_ZOOM_HALF:
                    frame = EDIT_RADAR_OUTLINE_112;
                    break;
                case EDIT_ZOOM_NORMAL:
                    frame = EDIT_RADAR_OUTLINE_56;
                    break;
            }
            radarX = m_viewX * ADVENTURE_RADAR_SMALL_CELL_PIXELS;
            radarY = m_viewY * ADVENTURE_RADAR_SMALL_CELL_PIXELS;
            break;
        case MAP_DIMENSION_MEDIUM:
            switch (m_zoomLevel) {
                case EDIT_ZOOM_FAR:
                    frame = EDIT_RADAR_OUTLINE_112;
                    break;
                case EDIT_ZOOM_HALF:
                    frame = EDIT_RADAR_OUTLINE_56;
                    break;
                case EDIT_ZOOM_NORMAL:
                    frame = EDIT_RADAR_OUTLINE_28;
                    break;
            }
            radarX = m_viewX * ADVENTURE_RADAR_MEDIUM_CELL_PIXELS;
            radarY = m_viewY * ADVENTURE_RADAR_MEDIUM_CELL_PIXELS;
            break;
        case MAP_DIMENSION_LARGE:
            switch (m_zoomLevel) {
                case EDIT_ZOOM_FAR:
                    frame = EDIT_RADAR_OUTLINE_75;
                    break;
                case EDIT_ZOOM_HALF:
                    frame = EDIT_RADAR_OUTLINE_37;
                    break;
                case EDIT_ZOOM_NORMAL:
                    frame = EDIT_RADAR_OUTLINE_19;
                    break;
            }
            radarX = m_viewX * EDIT_RADAR_LARGE_SCALE;
            radarY = m_viewY * EDIT_RADAR_LARGE_SCALE;
            break;
        default:
            switch (m_zoomLevel) {
                case EDIT_ZOOM_FAR:
                    frame = EDIT_RADAR_OUTLINE_56;
                    break;
                case EDIT_ZOOM_HALF:
                    frame = EDIT_RADAR_OUTLINE_28;
                    break;
                case EDIT_ZOOM_NORMAL:
                    frame = EDIT_RADAR_OUTLINE_14;
                    break;
            }
            radarX = m_viewX;
            radarY = m_viewY;
            break;
    }
    m_radarIcons->FillToBuffer(
        radarX + ADVENTURE_RADAR_LEFT, radarY + ADVENTURE_RADAR_TOP, frame, EDIT_RADAR_VIEW_COLOR,
        ICON_DRAW_NORMAL, NULL
    );
    UpdateKnobs(true);
    UpdateCursor();
}

void editManager::DrawCell(i32 x, i32 y, i32 column, i32 row, i32 layers) {
    gDrawCell = &gMap.Column(x)[y * gMap.width];
    gDrawX = column * gZoomTileSize[m_zoomLevel] + EDIT_VIEW_LEFT;
    gDrawY = row * gZoomTileSize[m_zoomLevel] + EDIT_VIEW_TOP;
    if (gGeneratingMap) {
        if (layers & EDIT_DRAW_OVERHANGING)
            TileToBitmapScale(
                m_cloudTiles[0],
                (x + y) & EDIT_CLOUD_TILE_MASK,
                gpWindowManager->m_screen,
                gDrawX,
                gDrawY,
                gZoomScale[m_zoomLevel]
            );
        return;
    }
    if (layers & EDIT_DRAW_GROUND) {
        gDrawTile = gDrawCell->m_flags;
        gDrawTile <<= EDIT_TILE_FLAG_SHIFT;
        gDrawTile |= gDrawCell->m_terrainImageIndex;
        TileToBitmapScale(
            m_groundTiles[0], gDrawTile, gpWindowManager->m_screen, gDrawX, gDrawY,
            gZoomScale[m_zoomLevel]
        );
    }
    if (layers & EDIT_DRAW_OBJECTS) {
        for (gDrawLayer = EDIT_LAYER_HIGH; gDrawLayer >= EDIT_LAYER_LOW; gDrawLayer--) {
            if (gDrawCell->m_objectIndex != MAPCELL_SPRITE_NONE
                && ((gDrawLayer == EDIT_LAYER_HIGH && gDrawCell->m_objectHighLayer)
                    || (gDrawLayer == EDIT_LAYER_MID && gDrawCell->m_objectShadow)
                    || (gDrawLayer == EDIT_LAYER_LOW && !gDrawCell->m_objectHighLayer
                        && !gDrawCell->m_objectShadow))) {
                if (gDrawCell->m_objectTileset == TILESET_MONS32)
                    IconToBitmapScale(
                        m_objectIcons[H2EnumIndex(gDrawCell->m_objectTileset)][0],
                        gpWindowManager->m_screen,
                        gDrawX,
                        gDrawY - EDIT_MONSTER_LIFT / gZoomScale[m_zoomLevel],
                        gDrawCell->m_objectIndex,
                        ICON_DRAW_CLIP,
                        0,
                        0,
                        EDIT_CLIP_VIEW,
                        EDIT_CLIP_VIEW,
                        gZoomCellSize[m_zoomLevel]
                    );
                else if (gDrawCell->m_objectTileset == TILESET_MINIHERO)
                    IconToBitmapScaleDouble(
                        m_objectIcons[H2EnumIndex(gDrawCell->m_objectTileset)][0],
                        gpWindowManager->m_screen,
                        gDrawX,
                        gDrawY - EDIT_HERO_LIFT / gZoomScale[m_zoomLevel],
                        gDrawCell->m_objectIndex,
                        ICON_DRAW_CLIP,
                        0,
                        0,
                        EDIT_CLIP_VIEW,
                        EDIT_CLIP_VIEW,
                        gZoomCellSize[m_zoomLevel]
                    );
                else
                    IconToBitmapScale(
                        m_objectIcons[H2EnumIndex(gDrawCell->m_objectTileset)][0],
                        gpWindowManager->m_screen,
                        gDrawX,
                        gDrawY,
                        gDrawCell->m_objectIndex,
                        ICON_DRAW_NO_CLIP,
                        0,
                        0,
                        EDIT_CLIP_SCREEN_W,
                        EDIT_CLIP_SCREEN_H,
                        gZoomCellSize[m_zoomLevel]
                    );
                if (gDrawCell->m_animatedObject) {
                    gDrawFrames = GetIconEntry(
                                      m_objectIcons[H2EnumIndex(gDrawCell->m_objectTileset)][0],
                                      gDrawCell->m_objectIndex
                                  )->flags;
                    if (gDrawCell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_MAGIC_GARDEN))
                        gDrawFrames--;
                    IconToBitmapScale(
                        m_objectIcons[H2EnumIndex(gDrawCell->m_objectTileset)][0],
                        gpWindowManager->m_screen,
                        gDrawX,
                        gDrawY,
                        gDrawCell->m_objectIndex + 1 + m_animationCounter % gDrawFrames,
                        ICON_DRAW_NO_CLIP,
                        0,
                        0,
                        EDIT_CLIP_SCREEN_W,
                        EDIT_CLIP_SCREEN_H,
                        gZoomCellSize[m_zoomLevel]
                    );
                }
            }
            if (gDrawCell->m_extraIndex
                && gMap.extras[gDrawCell->m_extraIndex].objectIndex != MAPCELL_SPRITE_NONE)
                gDrawExtra = &gMap.extras[gDrawCell->m_extraIndex];
            else
                gDrawExtra = NULL;
            while (gDrawExtra) {
                if ((gDrawLayer == EDIT_LAYER_HIGH && gDrawExtra->objectHighLayer)
                    || (gDrawLayer == EDIT_LAYER_MID && gDrawExtra->objectShadow)
                    || (gDrawLayer == EDIT_LAYER_LOW && !gDrawExtra->objectHighLayer
                        && !gDrawExtra->objectShadow)) {
                    if (gDrawExtra->objectTileset == TILESET_MONS32)
                        IconToBitmapScale(
                            m_objectIcons[H2EnumIndex(gDrawExtra->objectTileset)][0],
                            gpWindowManager->m_screen,
                            gDrawX,
                            gDrawY - EDIT_MONSTER_LIFT / gZoomScale[m_zoomLevel],
                            gDrawExtra->objectIndex,
                            ICON_DRAW_CLIP,
                            0,
                            0,
                            EDIT_CLIP_VIEW,
                            EDIT_CLIP_VIEW,
                            gZoomCellSize[m_zoomLevel]
                        );
                    else if (gDrawExtra->objectTileset == TILESET_MINIHERO)
                        IconToBitmapScaleDouble(
                            m_objectIcons[H2EnumIndex(gDrawExtra->objectTileset)][0],
                            gpWindowManager->m_screen,
                            gDrawX,
                            gDrawY - EDIT_HERO_LIFT / gZoomScale[m_zoomLevel],
                            gDrawExtra->objectIndex,
                            ICON_DRAW_CLIP,
                            0,
                            0,
                            EDIT_CLIP_VIEW,
                            EDIT_CLIP_VIEW,
                            gZoomCellSize[m_zoomLevel]
                        );
                    else
                        IconToBitmapScale(
                            m_objectIcons[H2EnumIndex(gDrawExtra->objectTileset)][0],
                            gpWindowManager->m_screen,
                            gDrawX,
                            gDrawY,
                            gDrawExtra->objectIndex,
                            ICON_DRAW_NO_CLIP,
                            0,
                            0,
                            EDIT_CLIP_SCREEN_W,
                            EDIT_CLIP_SCREEN_H,
                            gZoomCellSize[m_zoomLevel]
                        );
                    if (gDrawExtra->animatedObject) {
                        gDrawFrames = GetIconEntry(
                                          m_objectIcons[H2EnumIndex(gDrawExtra->objectTileset)][0],
                                          gDrawExtra->objectIndex
                                      )->flags;
                        IconToBitmapScale(
                            m_objectIcons[H2EnumIndex(gDrawExtra->objectTileset)][0],
                            gpWindowManager->m_screen,
                            gDrawX,
                            gDrawY,
                            gDrawExtra->objectIndex + 1 + m_animationCounter % gDrawFrames,
                            ICON_DRAW_NO_CLIP,
                            0,
                            0,
                            EDIT_CLIP_SCREEN_W,
                            EDIT_CLIP_SCREEN_H,
                            gZoomCellSize[m_zoomLevel]
                        );
                    }
                }
                if (gDrawExtra->nextIndex
                    && gMap.extras[gDrawExtra->nextIndex].objectIndex != MAPCELL_SPRITE_NONE)
                    gDrawExtra = &gMap.extras[gDrawExtra->nextIndex];
                else
                    gDrawExtra = NULL;
            }
        }
    }
    if (layers & EDIT_DRAW_OVERHANGING) {
        if (gDrawCell->m_overlayIndex != MAPCELL_SPRITE_NONE) {
            IconToBitmapScale(
                m_objectIcons[H2EnumIndex(gDrawCell->m_overlayTileset)][0],
                gpWindowManager->m_screen,
                gDrawX,
                gDrawY,
                gDrawCell->m_overlayIndex,
                ICON_DRAW_NO_CLIP,
                0,
                0,
                EDIT_CLIP_SCREEN_W,
                EDIT_CLIP_SCREEN_H,
                gZoomCellSize[m_zoomLevel]
            );
            if (gDrawCell->m_animatedOverlay) {
                gDrawFrames = GetIconEntry(
                                  m_objectIcons[H2EnumIndex(gDrawCell->m_overlayTileset)][0],
                                  gDrawCell->m_overlayIndex
                              )->flags;
                IconToBitmapScale(
                    m_objectIcons[H2EnumIndex(gDrawCell->m_overlayTileset)][0],
                    gpWindowManager->m_screen,
                    gDrawX,
                    gDrawY,
                    gDrawCell->m_overlayIndex + 1 + m_animationCounter % gDrawFrames,
                    ICON_DRAW_NO_CLIP,
                    0,
                    0,
                    EDIT_CLIP_SCREEN_W,
                    EDIT_CLIP_SCREEN_H,
                    gZoomCellSize[m_zoomLevel]
                );
            }
        }
        if (gDrawCell->m_extraIndex
            && gMap.extras[gDrawCell->m_extraIndex].overlayIndex != MAPCELL_SPRITE_NONE)
            gDrawExtra = &gMap.extras[gDrawCell->m_extraIndex];
        else
            gDrawExtra = NULL;
        while (gDrawExtra) {
            IconToBitmapScale(
                m_objectIcons[H2EnumIndex(gDrawExtra->overlayTileset)][0],
                gpWindowManager->m_screen,
                gDrawX,
                gDrawY,
                gDrawExtra->overlayIndex,
                ICON_DRAW_NO_CLIP,
                0,
                0,
                EDIT_CLIP_SCREEN_W,
                EDIT_CLIP_SCREEN_H,
                gZoomCellSize[m_zoomLevel]
            );
            if (gDrawExtra->animatedOverlay) {
                gDrawFrames = GetIconEntry(
                                  m_objectIcons[H2EnumIndex(gDrawExtra->overlayTileset)][0],
                                  gDrawExtra->overlayIndex
                              )->flags;
                IconToBitmapScale(
                    m_objectIcons[H2EnumIndex(gDrawExtra->overlayTileset)][0],
                    gpWindowManager->m_screen,
                    gDrawX,
                    gDrawY,
                    gDrawExtra->overlayIndex + 1 + m_animationCounter % gDrawFrames,
                    ICON_DRAW_NO_CLIP,
                    0,
                    0,
                    EDIT_CLIP_SCREEN_W,
                    EDIT_CLIP_SCREEN_H,
                    gZoomCellSize[m_zoomLevel]
                );
            }
            if (gDrawExtra->nextIndex
                && gMap.extras[gDrawExtra->nextIndex].overlayIndex != MAPCELL_SPRITE_NONE)
                gDrawExtra = &gMap.extras[gDrawExtra->nextIndex];
            else
                gDrawExtra = NULL;
        }
    }
}

void editManager::ToggleZoom(void) {
    if (m_zoomLevel == EDIT_ZOOM_NORMAL) {
        if (MAP_HEIGHT == MAP_DIMENSION_SMALL) {
            m_zoomLevel = EDIT_ZOOM_HALF;
            Scroll(-EDIT_ZOOM_SHIFT_SMALL, -EDIT_ZOOM_SHIFT_SMALL);
        } else {
            m_zoomLevel = EDIT_ZOOM_FAR;
            Scroll(-EDIT_ZOOM_SHIFT_LARGE, -EDIT_ZOOM_SHIFT_LARGE);
        }
    } else if (m_zoomLevel == EDIT_ZOOM_FAR) {
        m_zoomLevel = EDIT_ZOOM_HALF;
        Scroll(EDIT_ZOOM_SHIFT_BACK, EDIT_ZOOM_SHIFT_BACK);
    } else {
        m_zoomLevel = EDIT_ZOOM_NORMAL;
        Scroll(EDIT_ZOOM_SHIFT_SMALL, EDIT_ZOOM_SHIFT_SMALL);
    }
    DrawView(m_viewX, m_viewY);
    DrawRadar(true);
    UpdateMapView();
}


void editManager::SelectTool(i32 tool) {
    i32 i;
    tag_message msg;

    if (m_tool == tool)
        return;
    if (m_toolManager) {
        gpExec->RemoveManager(m_toolManager);
        delete m_toolManager;
        m_toolManager = NULL;
    }
    for (i = 0; i < EDIT_TOOL_COUNT; i++) {
        msg.type = MESSAGE_WIDGET;
        msg.payload.widget.id = i + EDIT_CONTROL_TOOL_FIRST;
        msg.payload.widget.command = WIDGET_COMMAND_SET_FRAME;
        msg.payload.widget.data.value = (i == tool) + i * EDIT_BUTTON_FRAMES;
        m_window->BroadcastMessage(msg);
    }
    if (tool != EDIT_TOOL_NONE) {
        msg.payload.widget.id = EDIT_CONTROL_TOOL_PANEL;
        msg.payload.widget.data.value = tool;
        m_window->BroadcastMessage(msg);
    }
    switch (tool) {
        case EDIT_TOOL_TERRAIN:
            m_toolManager = new terrainManager;
            break;
        case EDIT_TOOL_OBJECT:
            m_toolManager = new overlayManager;
            break;
        case EDIT_TOOL_DETAIL:
            m_toolManager = new eventsManager;
            break;
        case EDIT_TOOL_ERASE:
            m_toolManager = new clearManager;
            break;
        case EDIT_TOOL_STREAM:
            m_toolManager = new lineManager;
            gLineType = LINE_STREAM;
            SetLineType(gLineType);
            break;
        case EDIT_TOOL_ROAD:
            m_toolManager = new lineManager;
            gLineType = LINE_ROAD;
            SetLineType(gLineType);
            break;
    }
    if (m_toolManager) {
        if (!gpExec->AddManager(m_toolManager, EDIT_TOOL_PRIORITY)) {
            m_tool = tool;
        } else {
            m_toolManager = NULL;
            m_tool = EDIT_TOOL_NONE;
        }
    } else {
        m_tool = EDIT_TOOL_NONE;
    }
    m_window->DrawWindow();
}

void editManager::Scroll(i32 dx, i32 dy) {
    m_viewX += dx;
    if (m_viewX < 0)
        m_viewX = 0;
    if (m_viewX > MAP_WIDTH - gZoomViewCells[m_zoomLevel])
        m_viewX = MAP_WIDTH - gZoomViewCells[m_zoomLevel];
    m_viewY += dy;
    if (m_viewY < 0)
        m_viewY = 0;
    if (m_viewY > MAP_HEIGHT - gZoomViewCells[m_zoomLevel])
        m_viewY = MAP_HEIGHT - gZoomViewCells[m_zoomLevel];
    DrawView(m_viewX, m_viewY);
    UpdateMapView();
    DrawRadar(true);
}

void editManager::UpdateKnobs(b32 updateScreen) {
    double scaleX;
    double scaleY;
    i32 xPos [[maybe_unused]];
    i32 yPos [[maybe_unused]];

    scaleX = static_cast<double>(EDIT_KNOB_SCALE_SPAN)
             / (MAP_WIDTH - gZoomViewCells[m_zoomLevel] + 1);
    scaleY = static_cast<double>(EDIT_KNOB_SCALE_SPAN)
             / (MAP_HEIGHT - gZoomViewCells[m_zoomLevel] + 1);
    xPos = m_viewX * scaleX;
    yPos = m_viewY * scaleY;
    if (MAP_WIDTH > gZoomViewCells[m_zoomLevel])
        m_horizontalKnob->m_x
            = m_viewX * (static_cast<double>(EDIT_KNOB_TRAVEL)
                         / ((MAP_WIDTH + 1 - gZoomViewCells[m_zoomLevel]) - 1.0))
            + static_cast<double>(EDIT_KNOB_FIRST);
    else
        m_horizontalKnob->m_x = EDIT_KNOB_PARKED;
    if (MAP_HEIGHT > gZoomViewCells[m_zoomLevel])
        m_verticalKnob->m_y
            = m_viewY * (static_cast<double>(EDIT_KNOB_TRAVEL)
                         / ((MAP_HEIGHT + 1 - gZoomViewCells[m_zoomLevel]) - 1.0))
            + static_cast<double>(EDIT_KNOB_FIRST);
    else
        m_verticalKnob->m_y = EDIT_KNOB_PARKED;
    m_window->DrawWindow(updateScreen, EDIT_CONTROL_HORIZONTAL_TRACK, EDIT_CONTROL_SCROLL_LAST);
}

void editManager::PaintGround(i32 column, i32 row, i32 width, i32 height, i32 terrain) {
    i32 startY;
    i32 startX;
    i32 j;
    i32 cellPixels [[maybe_unused]];
    i32 redrawTop [[maybe_unused]];
    i32 i;
    i32 redrawLeft [[maybe_unused]];
    i32 redrawWidth [[maybe_unused]];

    startX = m_viewX + column;
    startY = m_viewY + row;
    gEditManager->ClearArea(startX, startY, width, height, EDIT_CLEAR_ALL, false, false);
    for (i = 0; i < width; i++)
        for (j = 0; j < height; j++)
            gMap.CellAt(startX + i, startY + j)->m_terrainImageIndex
                = ChooseGroundTile(terrain, EDIT_SHAPE_PLAIN, true, startX + i, startY + j, false,
                                   1.0f);
}

void editManager::FillGround(i32 x, i32 y, i32 width, i32 height, i32 terrain) {
    i32 i;
    i32 j;

    gEditManager->ClearArea(x, y, width, height, EDIT_CLEAR_ALL, false, false);
    for (i = x; i < x + width; i++) {
        for (j = y; j < y + height; j++) {
            gMap.CellAt(i, j)->m_terrainImageIndex
                = ChooseGroundTile(terrain, EDIT_SHAPE_PLAIN, true, i, j, false, 1.0f);
            gMap.Column(i)[j * gMap.width].m_flags &= H2EnumIndex(MAP_CELL_GROUND_KEEP);
        }
    }
}


void SetCellGround(i32 x, i32 y, i32 terrain, i32 shape) {
    mapCell* cell;

    cell = &gMap.Column(x)[y * gMap.width];
    if (H2EnumIndex(giGroundToTerrain[cell->m_terrainImageIndex]) == terrain
        && (giGroundShape[cell->m_terrainImageIndex] & EDIT_SHAPE_MASK)
               == (shape & EDIT_SHAPE_MASK))
        return;
    cell->m_terrainImageIndex = ChooseGroundTile(terrain, shape, true, x, y, false, 1.0f);
}


void editManager::DoRadar(void) {
    tag_message input;
    i32 x;
    tag_message mouseMove;
    i32 y;
    float scale;

    gpMouseManager->MouseCoords(x, y);
    if (x < ADVENTURE_RADAR_LEFT || x > ADVENTURE_RADAR_RIGHT
        || y < ADVENTURE_RADAR_TOP || y > ADVENTURE_RADAR_BOTTOM)
        return;
    switch (MAP_HEIGHT) {
        case MAP_DIMENSION_SMALL:
            scale = ADVENTURE_RADAR_SMALL_CELL_PIXELS;
            break;
        case MAP_DIMENSION_MEDIUM:
            scale = ADVENTURE_RADAR_MEDIUM_CELL_PIXELS;
            break;
        case MAP_DIMENSION_LARGE:
            scale = static_cast<float>(EDIT_RADAR_LARGE_SCALE);
            break;
        default:
            scale = 1.0f;
            break;
    }
    x = (x - ADVENTURE_RADAR_LEFT) / scale;
    y = (y - ADVENTURE_RADAR_TOP) / scale;
    m_viewX = x - gZoomViewCells[m_zoomLevel] / 2;
    if (m_viewX + gZoomViewCells[m_zoomLevel] > MAP_WIDTH)
        m_viewX = MAP_WIDTH - gZoomViewCells[m_zoomLevel];
    m_viewY = y - gZoomViewCells[m_zoomLevel] / 2;
    if (m_viewY + gZoomViewCells[m_zoomLevel] > MAP_HEIGHT)
        m_viewY = MAP_HEIGHT - gZoomViewCells[m_zoomLevel];
    if (m_viewX < 0)
        m_viewX = 0;
    if (m_viewY < 0)
        m_viewY = 0;
    DrawMap();
    DrawRadar(true);
    UpdateMapView();
    input = gpInputManager->GetEvent();
    while (input.type != MESSAGE_LEFT_BUTTON_UP && input.type != MESSAGE_RIGHT_BUTTON_UP) {
        Process1WindowsMessage();
        if (input.type == MESSAGE_MOUSE_MOVE) {
            while (input.type == MESSAGE_MOUSE_MOVE) {
                mouseMove = input;
                input = gpInputManager->GetEvent();
            }
            gpMouseManager->Main(mouseMove);
            x = (mouseMove.payload.mouse.x - ADVENTURE_RADAR_LEFT) / scale;
            y = (mouseMove.payload.mouse.y - ADVENTURE_RADAR_TOP) / scale;
            m_viewX = x - gZoomViewCells[m_zoomLevel] / 2;
            if (m_viewX + gZoomViewCells[m_zoomLevel] > MAP_WIDTH)
                m_viewX = MAP_WIDTH - gZoomViewCells[m_zoomLevel];
            m_viewY = y - gZoomViewCells[m_zoomLevel] / 2;
            if (m_viewY + gZoomViewCells[m_zoomLevel] > MAP_HEIGHT)
                m_viewY = MAP_HEIGHT - gZoomViewCells[m_zoomLevel];
            if (m_viewX < 0)
                m_viewX = 0;
            if (m_viewY < 0)
                m_viewY = 0;
            DrawMap();
            DrawRadar(true);
            UpdateMapView();
        } else {
            input = gpInputManager->GetEvent();
        }
    }
}

void editManager::DoHorizontalKnob(void) {
    double scale;
    tag_message latest;
    i32 x;
    tag_message message;
    i32 y;
    i32 newX;

    scale = static_cast<double>(EDIT_KNOB_SCALE_SPAN)
            / (MAP_WIDTH - gZoomViewCells[m_zoomLevel] + 1);
    gpMouseManager->MouseCoords(x, y);
    gpInputManager->Flush();
    message.type = MESSAGE_MOUSE_MOVE;
    message.payload.mouse.x = x;
    message.payload.mouse.y = y;
    while (message.type != MESSAGE_LEFT_BUTTON_UP && message.type != MESSAGE_RIGHT_BUTTON_UP) {
        Process1WindowsMessage();
        if (message.type == MESSAGE_MOUSE_MOVE) {
            latest = message;
            while (message.type == MESSAGE_MOUSE_MOVE) {
                latest = message;
                message = gpInputManager->GetEvent();
            }
            gpMouseManager->Main(latest);
            m_horizontalKnob->m_x = latest.payload.mouse.x;
            newX = latest.payload.mouse.x;
            newX = (newX - EDIT_KNOB_DRAG_ORIGIN) / scale;
            newX = newX + 0.5;
            if (m_viewX != newX) {
                if (newX > MAP_WIDTH - gZoomViewCells[m_zoomLevel])
                    newX = MAP_WIDTH - gZoomViewCells[m_zoomLevel];
                if (newX < 0)
                    newX = 0;
                m_viewX = newX;
                DrawMap();
                UpdateMapView();
                DrawRadar(true);
            }
        } else {
            message = gpInputManager->GetEvent();
        }
    }
    m_horizontalKnob->m_flags &= ~WIDGET_FLAG_SELECTED;
    m_horizontalTrack->m_flags &= ~WIDGET_FLAG_SELECTED;
}

void editManager::DoVerticalKnob(void) {
    double scale;
    tag_message latest;
    i32 x;
    tag_message message;
    i32 y;
    i32 newY;

    scale = static_cast<double>(EDIT_KNOB_SCALE_SPAN)
            / (MAP_HEIGHT - gZoomViewCells[m_zoomLevel] + 1);
    gpMouseManager->MouseCoords(x, y);
    gpInputManager->Flush();
    message.type = MESSAGE_MOUSE_MOVE;
    message.payload.mouse.x = x;
    message.payload.mouse.y = y;
    while (message.type != MESSAGE_LEFT_BUTTON_UP && message.type != MESSAGE_RIGHT_BUTTON_UP) {
        Process1WindowsMessage();
        if (message.type == MESSAGE_MOUSE_MOVE) {
            latest = message;
            while (message.type == MESSAGE_MOUSE_MOVE) {
                latest = message;
                message = gpInputManager->GetEvent();
            }
            gpMouseManager->Main(latest);
            m_verticalKnob->m_y = latest.payload.mouse.y;
            newY = latest.payload.mouse.y;
            newY = (newY - EDIT_KNOB_DRAG_ORIGIN) / scale;
            newY = newY + 0.5;
            if (m_viewY != newY) {
                if (newY > MAP_HEIGHT - gZoomViewCells[m_zoomLevel])
                    newY = MAP_HEIGHT - gZoomViewCells[m_zoomLevel];
                if (newY < 0)
                    newY = 0;
                m_viewY = newY;
                DrawMap();
                UpdateMapView();
                DrawRadar(true);
            }
        } else {
            message = gpInputManager->GetEvent();
        }
    }
    m_verticalKnob->m_flags &= ~WIDGET_FLAG_SELECTED;
    m_verticalTrack->m_flags &= ~WIDGET_FLAG_SELECTED;
}


char* gEditErrors[EDIT_MANAGER_ERROR_CAPACITY];
i32 gEditErrorCount;


void editManager::CheckObjects(void) {
    char barrierColors[KB_BARRIER_COLOR_NAME_COUNT];
    i32 gates[EDIT_TRAVEL_GATE_KINDS];
    char tentColors[KB_BARRIER_COLOR_NAME_COUNT];
    i32 x;
    i32 whirlpools;
    i32 y;
    i32 i;

    whirlpools = 0;
    for (i = 0; i < KB_BARRIER_COLOR_NAME_COUNT; i++) {
        barrierColors[i] = 0;
        tentColors[i] = 0;
    }
    gates[0] = 0;
    gates[1] = 0;
    gates[2] = 0;
    for (y = 0; y < MAP_HEIGHT; y++) {
        for (x = 0; x < MAP_WIDTH; x++) {
            if (gMap.CellAt(x, y)->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_BARRIER))
                barrierColors[gMap.CellAt(x, y)->m_objectMetadata & EDIT_BARRIER_COLOR_MASK] = 1;
            if (gMap.CellAt(x, y)->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_TRAVELER_TENT))
                tentColors[gMap.CellAt(x, y)->m_objectMetadata & EDIT_BARRIER_COLOR_MASK] = 1;
            if (gMap.CellAt(x, y)->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_STONE_LITHS))
                gates[gMap.CellAt(x, y)->m_objectIndex % EDIT_TRAVEL_GATE_FRAMES
                      / EDIT_TRAVEL_GATE_KIND_FRAMES]++;
            if (x < MAP_WIDTH - EDIT_WHIRLPOOL_SECOND_CELL_X
                && y < MAP_HEIGHT - EDIT_WHIRLPOOL_SECOND_CELL_Y
                && MAP_TRIGGER_OBJECT(gMap.CellAt(x, y)->m_triggerType) == MAP_OBJECT_WHIRLPOOL
                && MAP_TRIGGER_OBJECT(gMap.CellAt(x + EDIT_WHIRLPOOL_SECOND_CELL_X,
                                                  y + EDIT_WHIRLPOOL_SECOND_CELL_Y)
                                          ->m_triggerType)
                       == MAP_OBJECT_WHIRLPOOL)
                whirlpools++;
        }
    }
    if (gates[0] == 1 || gates[1] == 1 || gates[2] == 1)
        AddError(localization::Tr("editor.check.travel_gate.single"));
    if (whirlpools == 1)
        AddError(localization::Tr("editor.check.whirlpool.single"));
    for (i = 0; i < KB_BARRIER_COLOR_NAME_COUNT; i++) {
        if (barrierColors[i] && !tentColors[i]) {
            sprintf(gText, localization::Tr("editor.check.barrier.no_tent"), xBarrierColor[i],
                    xBarrierColor[i]);
            AddError(gText);
        }
    }
}


void ClearTextFile(void) {
    i32 handle;
    char buffer[EDIT_TEXT_CLEAR_SIZE];

    handle = open(gTextFileName, _O_WRONLY | _O_CREAT | _O_TRUNC | _O_TEXT, _S_IWRITE);
    if (handle == -1)
        return;
    strcpy(buffer, " ");
    write(handle, buffer, strlen(buffer));
    close(handle);
}

void AppendTextLine(const char* text) {
    FILE* out;
    char buffer[EDIT_TEXT_LINE_SIZE];

    out = fopen(gTextFileName, "at+");
    if (!out)
        return;
    strcpy(buffer, text);
    strcat(buffer, "\n");
    fputs(buffer, out);
    fclose(out);
}

void WriteTextHeader(i32 x, i32 y, const char* kind) {
    AppendTextLine("");
    sprintf(gText, "(x:% 3d, y:% 3d)    ***%s***", x, y, kind);
    AppendTextLine(gText);
}


void editManager::ExportMapText(void) {
    i32 x;
    i32 i;
    i32 y;
    char textName[EDIT_TEXT_FILE_NAME_SIZE];
    char* ext;
    TownExtra* townData;
    mapCell* cell;

    gTextFileName = textName;
    strcpy(textName, gMapFileName);
    ext = textName + strlen(gMapFileName) - EDIT_TEXT_EXTENSION_LENGTH;
    strcpy(ext, ".TXT");
    ClearTextFile();
    AppendTextLine("========================================");
    sprintf(gText, "Text for file:  %s", gMapFileName);
    AppendTextLine(gText);
    AppendTextLine("");
    sprintf(gText, "Map Name: %s", gEditMapHeader.name);
    AppendTextLine(gText);
    AppendTextLine("");
    AppendTextLine("Map Description:");
    AppendTextLine(gEditMapHeader.description);
    AppendTextLine("");
    AppendTextLine("");
    AppendTextLine("Rumours:");
    for (i = 0; i < gEditMapHeader.rumourCount; i++) {
        AppendTextLine(static_cast<rumourEventExtra*>(gEditManager->m_extras[gRumourExtras[i]])->text);
        AppendTextLine("");
    }
    AppendTextLine("");
    AppendTextLine("");
    AppendTextLine("Timed Events:");
    for (i = 0; i < gEditMapHeader.timeEventCount; i++) {
        sprintf(gText, "Day %d: %s",
                static_cast<EventExtra*>(gEditManager->m_extras[gTimeEventExtras[i]])->firstDay,
                static_cast<EventExtra*>(gEditManager->m_extras[gTimeEventExtras[i]])->message);
        AppendTextLine(gText);
        AppendTextLine("");
    }
    AppendTextLine("");
    AppendTextLine("");
    AppendTextLine("Map Stuff:");
    for (x = 0; x < MAP_WIDTH; x++) {
        for (y = 0; y < MAP_HEIGHT; y++) {
            cell = gMap.CellAt(x, y);
            switch (cell->m_triggerType) {
                case MAP_ACTION_TRIGGER(MAP_OBJECT_BOTTLE):
                    WriteTextHeader(x, y, "Bottle");
                    goto message;
                case MAP_ACTION_TRIGGER(MAP_OBJECT_SIGN):
                    WriteTextHeader(x, y, "Sign");
                message:
                    AppendTextLine(
                        static_cast<signEventExtra*>(gEditManager->m_extras[cell->m_objectMetadata])->text);
                    break;
                case MAP_ACTION_TRIGGER(MAP_OBJECT_MAP_EVENT):
                    WriteTextHeader(x, y, "Place Event");
                    AppendTextLine(
                        static_cast<EventExtra*>(gEditManager->m_extras[cell->m_objectMetadata])->message);
                    break;
                case MAP_ACTION_TRIGGER(MAP_OBJECT_SPHINX):
                    WriteTextHeader(x, y, "Sphinx");
                    AppendTextLine("Riddle:");
                    AppendTextLine(
                        static_cast<mapEventExtra*>(gEditManager->m_extras[cell->m_objectMetadata])->riddle);
                    AppendTextLine("Answers:");
                    for (i = 0;
                         i < static_cast<mapEventExtra*>(gEditManager->m_extras[cell->m_objectMetadata])
                                 ->answerCount;
                         i++)
                        AppendTextLine(static_cast<mapEventExtra*>(
                                           gEditManager->m_extras[cell->m_objectMetadata])
                                           ->answers[i]);
                    break;
            }
        }
    }
    AppendTextLine("");
    AppendTextLine("");
    AppendTextLine("Towns with captains:");
    for (x = 0; x < MAP_WIDTH; x++) {
        for (y = 0; y < MAP_HEIGHT; y++) {
            cell = gMap.CellAt(x, y);
            switch (cell->m_triggerType) {
                case MAP_ACTION_TRIGGER(MAP_OBJECT_CASTLE):
                case MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_TOWN):
                    townData = static_cast<TownExtra*>(gEditManager->m_extras[cell->m_objectMetadata]);
                    if (!townData->isCastle && townData->hasCaptain) {
                        sprintf(gText, "Town at x:%d, y:%d", x, y);
                        AppendTextLine(gText);
                    }
                    break;
            }
        }
    }
    sprintf(gText, "Text successfully saved to %s", textName);
    NormalDialog(gText, NORMAL_DIALOG_INFO);
    gTextFileName = NULL;
}


void ReadTextLine(FILE* file, char* line) {
    fgets(line, EDIT_TEXT_READ_SIZE, file);
    line[strlen(line) - 1] = 0;
}

bool FindTextHeader(FILE* file, i32 x, i32 y, const char* kind) {
    char line [[maybe_unused]][EDIT_TEXT_LINE_SIZE];
    char* mark;
    i32 fileX;
    i32 fileY;

    ReadTextLine(file, gText);
    if (strcmp(gText, ""))
        return false;
    ReadTextLine(file, gText);
    sscanf(gText, "(x:%d, y:%d)", &fileX, &fileY);
    if (fileX != x || fileY != y)
        return false;
    mark = strchr(gText, '*');
    mark += EDIT_TEXT_HEADER_MARKS;
    mark[strlen(mark) - EDIT_TEXT_HEADER_MARKS] = 0;
    if (strcmp(mark, kind))
        return false;
    return true;
}


bool editManager::ImportMapText(void) {
    i32 x;
    i32 i;
    i32 y;
    char textName[EDIT_TEXT_FILE_NAME_SIZE];
    char* ext;
    mapCell* cell;

    gTextFileName = textName;
    strcpy(textName, gMapFileName);
    ext = textName + strlen(gMapFileName) - EDIT_TEXT_EXTENSION_LENGTH;
    strcpy(ext, ".TXT");
    textFile in;
    in.m_file = fopen(textName, "rt");
    if (!in)
        return false;
    gEditManager->m_mapChanged = true;
    ReadTextLine(in, gText);
    if (strcmp(" ========================================", gText))
        return false;
    ReadTextLine(in, gText);
    if (strncmp(gText, "Text for file:  ", EDIT_TEXT_FILE_TAG_LENGTH))
        return false;
    if (strcmp(gText + EDIT_TEXT_FILE_TAG_LENGTH, gMapFileName))
        return false;
    ReadTextLine(in, gText);
    if (strcmp(gText, ""))
        return false;
    ReadTextLine(in, gText);
    if (strncmp("Map Name: ", gText, EDIT_TEXT_NAME_TAG_LENGTH))
        return false;
    strncpy(gEditMapHeader.name, gText + EDIT_TEXT_NAME_TAG_LENGTH, MAP_HEADER_NAME_SIZE);
    gEditMapHeader.name[MAP_HEADER_NAME_SIZE - 1] = 0;
    ReadTextLine(in, gText);
    if (strcmp(gText, ""))
        return false;
    ReadTextLine(in, gText);
    if (strcmp(gText, "Map Description:"))
        return false;
    ReadTextLine(in, gText);
    ReadTextLine(in, gText);
    if (strcmp(gText, ""))
        return false;
    ReadTextLine(in, gText);
    if (strcmp(gText, ""))
        return false;
    ReadTextLine(in, gText);
    if (strcmp(gText, "Rumours:"))
        return false;
    for (i = 0; i < gEditMapHeader.rumourCount; i++) {
        i32 size;
        char head[sizeof(rumourEventExtra)];
        char* record;

        ReadTextLine(in, gText);
        memcpy(head, gEditManager->m_extras[gRumourExtras[i]], sizeof(rumourEventExtra));
        size = strlen(gText) + sizeof(rumourEventExtra);
        record = new char[size];
        memcpy(record, head, sizeof(rumourEventExtra));
        strcpy(record + offsetof(rumourEventExtra, text), gText);
        delete gEditManager->m_extras[gRumourExtras[i]];
        gEditManager->m_extras[gRumourExtras[i]] = record;
        gEditManager->m_extraSizes[gRumourExtras[i]] = size;
        ReadTextLine(in, gText);
        if (strcmp("", gText))
            return false;
    }
    ReadTextLine(in, gText);
    if (strcmp("", gText))
        return false;
    ReadTextLine(in, gText);
    if (strcmp("", gText))
        return false;
    ReadTextLine(in, gText);
    if (strcmp(gText, "Timed Events:"))
        return false;
    for (i = 0; i < gEditMapHeader.timeEventCount; i++) {
        i32 size;
        char* record;
        i32 date;
        char* text;
        char prefix[sizeof(EventExtra)];

        ReadTextLine(in, gText);
        if (strncmp(gText, "Day ", EDIT_TEXT_DAY_TAG_LENGTH))
            return false;
        sscanf(gText + EDIT_TEXT_DAY_TAG_LENGTH, "%d", &date);
        static_cast<EventExtra*>(gEditManager->m_extras[gTimeEventExtras[i]])->firstDay = date;
        text = strchr(gText + EDIT_TEXT_DAY_TAG_LENGTH, ':') + EDIT_TEXT_DAY_SEPARATOR_LENGTH;
        memcpy(prefix, gEditManager->m_extras[gTimeEventExtras[i]], sizeof(EventExtra));
        size = strlen(text) + sizeof(EventExtra);
        record = new char[size];
        memcpy(record, prefix, sizeof(EventExtra));
        strcpy(record + offsetof(EventExtra, message), text);
        delete gEditManager->m_extras[gTimeEventExtras[i]];
        gEditManager->m_extras[gTimeEventExtras[i]] = record;
        gEditManager->m_extraSizes[gTimeEventExtras[i]] = size;
        ReadTextLine(in, gText);
        if (strcmp("", gText))
            return false;
    }
    ReadTextLine(in, gText);
    if (strcmp("", gText))
        return false;
    ReadTextLine(in, gText);
    if (strcmp("", gText))
        return false;
    ReadTextLine(in, gText);
    if (strcmp(gText, "Map Stuff:"))
        return false;
    for (x = 0; x < MAP_WIDTH; x++) {
        for (y = 0; y < MAP_HEIGHT; y++) {
            i32 unused2 [[maybe_unused]];
            i32 unused [[maybe_unused]];
            char* newEvent;
            i32 length;
            char* riddleRecord;
            char sphinxHead[sizeof(mapEventExtra)];
            char bottleHead[sizeof(signEventExtra)];
            char* signCopy;
            char mapEventStart[sizeof(EventExtra)];

            cell = gMap.CellAt(x, y);
            switch (cell->m_triggerType) {
                case MAP_ACTION_TRIGGER(MAP_OBJECT_BOTTLE):
                    if (!FindTextHeader(in, x, y, "Bottle"))
                        return false;
                    goto message;
                case MAP_ACTION_TRIGGER(MAP_OBJECT_SIGN):
                    if (!FindTextHeader(in, x, y, "Sign"))
                        return false;
                message:
                    ReadTextLine(in, gText);
                    memcpy(bottleHead, gEditManager->m_extras[cell->m_objectMetadata],
                           sizeof(signEventExtra));
                    length = strlen(gText) + sizeof(signEventExtra);
                    if (!bottleHead[0])
                        strcpy(gText, "");
                    signCopy = new char[length];
                    memcpy(signCopy, bottleHead, sizeof(signEventExtra));
                    strcpy(signCopy + offsetof(signEventExtra, text), gText);
                    delete gEditManager->m_extras[cell->m_objectMetadata];
                    gEditManager->m_extras[cell->m_objectMetadata] = signCopy;
                    gEditManager->m_extraSizes[cell->m_objectMetadata] = length;
                    break;
                case MAP_ACTION_TRIGGER(MAP_OBJECT_MAP_EVENT):
                    if (!FindTextHeader(in, x, y, "Place Event"))
                        return false;
                    ReadTextLine(in, gText);
                    memcpy(mapEventStart, gEditManager->m_extras[cell->m_objectMetadata],
                           sizeof(EventExtra));
                    length = strlen(gText) + sizeof(EventExtra);
                    newEvent = new char[length];
                    memcpy(newEvent, mapEventStart, sizeof(EventExtra));
                    strcpy(newEvent + offsetof(EventExtra, message), gText);
                    delete gEditManager->m_extras[cell->m_objectMetadata];
                    gEditManager->m_extras[cell->m_objectMetadata] = newEvent;
                    gEditManager->m_extraSizes[cell->m_objectMetadata] = length;
                    break;
                case MAP_ACTION_TRIGGER(MAP_OBJECT_SPHINX):
                    if (!FindTextHeader(in, x, y, "Sphinx"))
                        return false;
                    ReadTextLine(in, gText);
                    if (strcmp(gText, "Riddle:"))
                        return false;
                    ReadTextLine(in, gText);
                    memcpy(sphinxHead, gEditManager->m_extras[cell->m_objectMetadata],
                           sizeof(mapEventExtra));
                    length = strlen(gText) + sizeof(mapEventExtra);
                    riddleRecord = new char[length];
                    memcpy(riddleRecord, sphinxHead, sizeof(mapEventExtra));
                    strcpy(riddleRecord + offsetof(mapEventExtra, riddle), gText);
                    delete gEditManager->m_extras[cell->m_objectMetadata];
                    gEditManager->m_extras[cell->m_objectMetadata] = riddleRecord;
                    gEditManager->m_extraSizes[cell->m_objectMetadata] = length;
                    ReadTextLine(in, gText);
                    if (strcmp(gText, "Answers:"))
                        return false;
                    for (i = 0;
                         i < static_cast<mapEventExtra*>(gEditManager->m_extras[cell->m_objectMetadata])
                                 ->answerCount;
                         i++) {
                        ReadTextLine(in, gText);
                        strncpy(static_cast<mapEventExtra*>(
                                    gEditManager->m_extras[cell->m_objectMetadata])
                                    ->answers[i],
                                gText, EDIT_SPHINX_ANSWER_LENGTH);
                    }
                    break;
            }
        }
    }
    ReadTextLine(in, gText);
    if (strcmp(gText, ""))
        return false;
    ReadTextLine(in, gText);
    if (strcmp(gText, ""))
        return false;
    ReadTextLine(in, gText);
    if (strcmp(gText, "Towns with captains:"))
        return false;
    for (x = 0; x < MAP_WIDTH; x++) {
        for (y = 0; y < MAP_HEIGHT; y++) {
            TownExtra* town;
            i32 fileX;
            i32 fileY;

            cell = gMap.CellAt(x, y);
            switch (cell->m_triggerType) {
                case MAP_ACTION_TRIGGER(MAP_OBJECT_CASTLE):
                case MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_TOWN):
                    town = static_cast<TownExtra*>(gEditManager->m_extras[cell->m_objectMetadata]);
                    if (!town->isCastle && town->hasCaptain) {
                        ReadTextLine(in, gText);
                        if (strncmp(gText, "Town at ", EDIT_TEXT_TOWN_TAG_LENGTH))
                            return false;
                        sscanf(gText + EDIT_TEXT_TOWN_TAG_LENGTH, "x:%d, y:%d", &fileX, &fileY);
                        if (fileX != x || fileY != y)
                            return false;
                    }
                    break;
            }
        }
    }
    sprintf(gText, localization::Tr("editor.text.imported"), textName);
    NormalDialog(gText, NORMAL_DIALOG_INFO);
    return true;
}


textFile::textFile(void) {
    m_file = NULL;
}

textFile::~textFile() {
    if (m_file)
        fclose(m_file);
}

textFile::operator FILE*(void) {
    return m_file;
}


void editManager::UpdateTriggers(void) {
    i32 type;
    i32 x;
    i32 temp [[maybe_unused]];
    mapCell* cell;
    i32 y;
    i32 lineType;

    gMap.Compact();
    cell = NULL;
    temp = 0;
    for (y = 0; y < MAP_HEIGHT; y++)
        for (x = 0; x < MAP_WIDTH; x++)
            if (gMap.CellAt(x, y)->m_triggerType == MAP_OBJECT_COAST)
                gMap.CellAt(x, y)->m_triggerType = MAP_OBJECT_NONE;
    for (y = 0; y < MAP_HEIGHT; y++) {
        for (x = 0; x < MAP_WIDTH; x++) {
            cell = gMap.CellAt(x, y);
            if (!(cell->m_triggerType & MAP_TRIGGER_ACTION_FLAG)
                && cell->m_triggerType != MAP_OBJECT_COAST) {
                type = OverlayTypeAt(x, y);
                if (type != OVERLAY_NONE) {
                    cell->m_triggerType = gOverlayTypes[type].trigger;
                    if ((type == EDIT_TYPE_ABANDONED_MINE_A
                         || (type == EDIT_TYPE_ABANDONED_MINE_B && x > 0 && x < MAP_WIDTH - 2
                             && y < MAP_HEIGHT - 2 && y > 0))
                        && OverlayTypeAt(x - 1, y) == type && OverlayTypeAt(x + 1, y) == type
                        && OverlayTypeAt(x, y - 1) == type && OverlayTypeAt(x, y + 1) != type)
                        cell->m_triggerType = gOverlayTypes[type].trigger | MAP_TRIGGER_ACTION_FLAG;
                    if (type == OVERLAY_RANDOM_MONSTER)
                        cell->m_triggerType = gOverlayTypes[type].trigger | MAP_TRIGGER_ACTION_FLAG;
                } else {
                    cell->m_triggerType = MAP_OBJECT_NONE;
                }
                if (!(cell->m_triggerType & MAP_TRIGGER_ACTION_FLAG)
                    && cell->m_triggerType != MAP_OBJECT_CASTLE
                    && cell->m_triggerType != MAP_OBJECT_RANDOM_TOWN
                    && cell->m_triggerType != MAP_OBJECT_RANDOM_CASTLE)
                    SetCoast(x, y);
                else if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_BOAT))
                    SetCoast(x, y);
            } else if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_BOAT)) {
                SetCoast(x, y);
            }
            if (giGroundToTerrain[cell->m_terrainImageIndex] == TERRAIN_WATER
                && (giGroundShape[cell->m_terrainImageIndex] == EDIT_SHAPE_NORTH_EDGE
                    || giGroundShape[cell->m_terrainImageIndex] == EDIT_SHAPE_NORTH_EDGE_ALT
                    || giGroundShape[cell->m_terrainImageIndex] == EDIT_SHAPE_NORTH_EAST_CORNER
                    || giGroundShape[cell->m_terrainImageIndex] == EDIT_SHAPE_EAST_EDGE_ALT
                    || giGroundShape[cell->m_terrainImageIndex] == EDIT_SHAPE_EAST_EDGE
                    || giGroundShape[cell->m_terrainImageIndex] == EDIT_SHAPE_NORTH_EAST_INNER))
                cell->m_flags |= H2EnumIndex(MAP_CELL_SHORE);
            else
                cell->m_flags &= ~H2EnumIndex(MAP_CELL_SHORE);
            if (giGroundToTerrain[cell->m_terrainImageIndex] == TERRAIN_WATER
                && giGroundShape[cell->m_terrainImageIndex] == EDIT_SHAPE_NORTH_EAST_CORNER)
                cell->m_flags |= H2EnumIndex(MAP_CELL_SHORE_CORNER);
            else
                cell->m_flags &= ~H2EnumIndex(MAP_CELL_SHORE_CORNER);
        }
    }
    lineType = gLineType;
    BuildLineMap(0, 0, MAP_WIDTH - 1, MAP_HEIGHT - 1, true);
    for (y = 0; y < MAP_HEIGHT; y++)
        for (x = 0; x < MAP_WIDTH; x++)
            gMap.CellAt(x, y)->m_isRoad = *(gLineMap + x + y * MAP_WIDTH) != 0;
    gLineType = lineType;
}


b32 editManager::Confirm(const char* question) {
    NormalDialog(question, NORMAL_DIALOG_CONFIRM);
    if (gpWindowManager->m_dialogResult == NORMAL_DIALOG_YES)
        return true;
    return false;
}


b32 editManager::HasObject(i32 trigger) {
    i32 x;
    i32 y;

    for (y = 0; y < MAP_HEIGHT; y++)
        for (x = 0; x < MAP_WIDTH; x++)
            if (gMap.CellAt(x, y)->m_triggerType == trigger)
                return true;
    return false;
}


i32 editManager::CountArtifacts(void) {
    i32 count;
    i32 x;
    i32 y;

    count = 0;
    for (y = 0; y < MAP_HEIGHT; y++)
        for (x = 0; x < MAP_WIDTH; x++)
            if (MAP_TRIGGER_OBJECT(gMap.CellAt(x, y)->m_triggerType) == MAP_OBJECT_ARTIFACT
                || MAP_TRIGGER_OBJECT(gMap.CellAt(x, y)->m_triggerType)
                       == MAP_OBJECT_RANDOM_ARTIFACT)
                count++;
    return count;
}

i32 editManager::CountEvents(void) {
    i32 count;
    i32 x;
    i32 y;
    mapCell* cell;

    count = 0;
    for (y = 0; y < MAP_HEIGHT; y++) {
        for (x = 0; x < MAP_WIDTH; x++) {
            cell = gMap.CellAt(x, y);
            if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_MAP_EVENT))
                count++;
        }
    }
    return count;
}

i32 editManager::CountTowns(void) {
    i32 count;
    i32 x;
    i32 y;
    mapCell* cell;

    count = 0;
    for (y = 0; y < MAP_HEIGHT; y++) {
        for (x = 0; x < MAP_WIDTH; x++) {
            cell = gMap.CellAt(x, y);
            if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_TOWN)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_CASTLE)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_CASTLE))
                count++;
        }
    }
    return count;
}

i32 editManager::CountMines(void) {
    i32 y;
    i32 x;
    i32 mineTotal;
    mapCell* cell;

    mineTotal = 0;
    for (y = 0; y < MAP_HEIGHT; y++) {
        for (x = 0; x < MAP_WIDTH; x++) {
            cell = gMap.CellAt(x, y);
            if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_ABANDONED_MINE)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_MINE)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_SAWMILL)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_ALCHEMIST_LAB)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_EYE_OF_MAGI)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_DRAGON_CITY)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_LIGHTHOUSE))
                mineTotal++;
        }
    }
    return mineTotal;
}


void editManager::WriteTowns(i32 file) {
    i32 count;
    i32 setTowns [[maybe_unused]];
    i32 type;
    i32 setCastles [[maybe_unused]];
    i32 x;
    mapCell* cell;
    i32 y;
    i32 notUsed [[maybe_unused]];
    EditMapRecord empty;
    i32 castleCount [[maybe_unused]];
    i32 index [[maybe_unused]];
    TownExtra* townExtra;

    count = 0;
    castleCount = 0;
    setCastles = 0;
    setTowns = 0;
    cell = NULL;
    for (y = 0; y < MAP_HEIGHT; y++) {
        for (x = 0; x < MAP_WIDTH; x++) {
            cell = gMap.CellAt(x, y);
            if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_CASTLE)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_TOWN)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_CASTLE)) {
                write(file, &x, 1);
                write(file, &y, 1);
                townExtra = static_cast<TownExtra*>(gEditManager->m_extras[cell->m_objectMetadata]);
                type = H2EnumIndex(townExtra->faction);
                if (townExtra->isCastle)
                    type |= EDIT_MAP_CASTLE_FLAG;
                write(file, &type, 1);
                count++;
            }
        }
    }
    empty.x = EDIT_MAP_NO_RECORD;
    empty.y = EDIT_MAP_NO_RECORD;
    empty.type = 0;
    for (x = 0; x < EDIT_MAP_TOWN_RECORDS - count; x++)
        WRITE_FILE_VALUE(file, empty);
}


void editManager::WriteMines(i32 file) {
    u8 type;
    i32 lighthouseCount [[maybe_unused]];
    u8 cityX [[maybe_unused]];
    u8 cityY [[maybe_unused]];
    u8 x;
    mapCell* cell;
    u8 y;
    EditMapRecord empty;
    u8 lighthouseX [[maybe_unused]];
    i32 mineNumber;
    u8 lighthouseY [[maybe_unused]];
    i32 cityCount [[maybe_unused]];
    mapCell* markerCell;
    i32 extraIndex;

    cityX = EDIT_MAP_NO_RECORD;
    cityY = EDIT_MAP_NO_RECORD;
    lighthouseX = EDIT_MAP_NO_RECORD;
    lighthouseY = EDIT_MAP_NO_RECORD;
    lighthouseCount = 0;
    cityCount = 0;
    cell = NULL;
    empty.x = EDIT_MAP_NO_RECORD;
    empty.y = EDIT_MAP_NO_RECORD;
    empty.type = EDIT_MAP_NO_RECORD;
    mineNumber = 0;
    for (y = 0; y < MAP_HEIGHT; y++) {
        for (x = 0; x < MAP_WIDTH; x++) {
            cell = gMap.CellAt(x, y);
            if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_DRAGON_CITY)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_LIGHTHOUSE)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_MINE)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_SAWMILL)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_ALCHEMIST_LAB)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_ABANDONED_MINE)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_EYE_OF_MAGI)) {
                if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_LIGHTHOUSE)) {
                    type = EDIT_MINE_TYPE_LIGHTHOUSE;
                } else if (cell->m_triggerType
                           == MAP_ACTION_TRIGGER(MAP_OBJECT_ABANDONED_MINE)) {
                    type = EDIT_MINE_TYPE_ABANDONED_MINE;
                } else if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_DRAGON_CITY)) {
                    type = EDIT_MINE_TYPE_DRAGON_CITY;
                } else if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_EYE_OF_MAGI)) {
                    type = EDIT_MINE_TYPE_EYE_OF_MAGI;
                } else {
                    markerCell = gMap.CellAt(x, y);
                    extraIndex = markerCell->m_extraIndex;
                    while (extraIndex) {
                        if (gMap.Extra(extraIndex)->objectIndex != MAPCELL_SPRITE_NONE
                            && gMap.Extra(extraIndex)->objectTileset == TILESET_EXTRAOVR) {
                            type = gMap.Extra(extraIndex)->objectIndex + EDIT_MINE_TYPE_FIRST_ORE;
                            goto write;
                        }
                        extraIndex = gMap.Extra(extraIndex)->nextIndex;
                    }
                    if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_SAWMILL))
                        type = EDIT_MINE_TYPE_WOOD;
                    else
                        type = EDIT_MINE_TYPE_MERCURY;
                }
            write:
                WRITE_FILE_VALUE(file, x);
                WRITE_FILE_VALUE(file, y);
                WRITE_FILE_VALUE(file, type);
                sprintf(gText, "Mine %02d: (%02d,%02d) type: %02d\n", mineNumber, x, y, type);
                LogStr(gText);
                mineNumber++;
            }
        }
    }
    for (x = 0; x < EDIT_MAP_MINE_RECORDS - mineNumber; x++)
        WRITE_FILE_VALUE(file, empty);
}


void editManager::WriteArtifacts(i32 file [[maybe_unused]]) {
}

void editManager::WriteObelisks(i32 file) {
    u8 obeliskCount;
    i32 x;
    i32 y;
    mapCell* cell;

    obeliskCount = 0;
    cell = NULL;
    for (y = 0; y < MAP_HEIGHT; y++) {
        for (x = 0; x < MAP_WIDTH; x++) {
            cell = gMap.CellAt(x, y);
            if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_OBELISK))
                obeliskCount++;
        }
    }
    if (!obeliskCount)
        obeliskCount++;
    WRITE_FILE_VALUE(file, obeliskCount);
    if (obeliskCount > EDIT_MAP_OBELISK_LIMIT) {
        sprintf(gText, localization::Tr("editor.check.obelisks.many"), obeliskCount);
        AddError(gText);
    }
}


i32 editManager::SaveMap(char* name) {
    char path[EDIT_MAP_PATH_SIZE];
    char oldName[EDITOR_MAP_FILE_NAME_SIZE];
    i32 length;
    char* mark;
    i32 mapHeight [[maybe_unused]];
    const char* chars;
    i32 height [[maybe_unused]];
    char base[EDIT_MAP_BASE_NAME_SIZE];
    i32 n;
    i32 formatWord [[maybe_unused]];
    char* namePos;
    i32 file;
    char target[EDIT_MAP_TARGET_NAME_SIZE];

    chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_01234567890";
    if (gEditMapHeader.nameFileOnSave
        && strnicmp(gEditMapHeader.name, localization::Tr("editor.map.no_name"),
                    EDIT_MAP_NO_NAME_LENGTH)
        && strlen(gEditMapHeader.name) > 1) {
        namePos = gEditMapHeader.name;
        length = 0;
        memset(base, 0, sizeof(base));
        while (*namePos && length < EDIT_MAP_BASE_NAME_LENGTH) {
            if ((length == 0
                 && ((gEditMapHeader.name[0] >= 'A' && gEditMapHeader.name[0] <= 'Z')
                     || (gEditMapHeader.name[0] >= 'a' && gEditMapHeader.name[0] <= 'z')))
                || (length > 0 && FindToken(chars, *namePos))) {
                base[length] = *namePos;
                length++;
            }
            namePos++;
        }
        sprintf(target, "%s.%s", base, "MP2");
        sprintf(path, ".\\maps\\%s", target);
        file = open(path, _O_BINARY);
        if (file == -1) {
            strcpy(name, target);
            strcpy(gMapFileName, target);
            goto named;
        }
        base[EDIT_MAP_NUMBERED_BASE_LENGTH] = 0;
        close(file);
        for (n = 0; n < EDIT_MAP_NUMBERED_NAMES; n++) {
            sprintf(target, "%s_%02d.%s", base, n, "MP2");
            sprintf(path, ".\\maps\\%s", target);
            file = open(path, _O_BINARY);
            if (file == -1) {
                strcpy(name, target);
                strcpy(gMapFileName, target);
                goto named;
            }
            close(file);
        }
    }
named:
    gEditMapHeader.nameFileOnSave = false;
    CoalesceObjectData();
    ResetPlayerAvailability();
    RandomizeTownNames();
    ClearErrors();
    CheckObjects();
    UpdateTriggers();
    mark = FindLastToken(name, '.');
    mark[1] = 0;
    strcpy(oldName, name);
    if (UsesExpansionObjects()) {
        strcat(name, "MX2");
        strcat(oldName, "MP2");
    } else {
        strcat(name, "MP2");
        strcat(oldName, "MX2");
    }
    sprintf(path, ".\\maps\\%s", oldName);
    file = open(path, _O_BINARY);
    if (file != -1) {
        close(file);
        unlink(path);
    }
    sprintf(path, ".\\maps\\%s", name);
    file = open(path, _O_WRONLY | _O_CREAT | _O_TRUNC | _O_BINARY, _S_IWRITE);
    if (file == -1)
        return EDIT_MAP_FILE_ERROR;
    write(file, &gEditMapHeader, sizeof(gEditMapHeader));
    gMap.Write(file);
    WriteTowns(file);
    WriteMines(file);
    WriteObelisks(file);
    write(file, gRumourExtras, gEditMapHeader.rumourCount * sizeof(gRumourExtras[0]));
    write(file, gTimeEventExtras, gEditMapHeader.timeEventCount * sizeof(gTimeEventExtras[0]));
    WRITE_FILE_VALUE(file, m_extraCount);
    for (n = EDIT_MANAGER_FIRST_EXTRA; n < m_extraCount; n++) {
        WRITE_FILE_VALUE(file, m_extraSizes[n]);
        write(file, m_extras[n], m_extraSizes[n]);
    }
    WRITE_FILE_VALUE(file, gNextObjectLink);
    close(file);
    ShowErrors();
    return EDIT_MAP_FILE_OK;
}


i32 editManager::LoadMap(char* name) {
    char fileName[EDIT_MAP_PATH_SIZE];
    char tmpName[EDITOR_MAP_FILE_NAME_SIZE];
    i32 width [[maybe_unused]];
    u8 ignored[EDIT_MAP_SKIPPED_SIZE];
    i32 mapFormat [[maybe_unused]];
    i32 i;
    i32 handle;
    SMapHeader mapHeader;
    i32 height [[maybe_unused]];

    strcpy(tmpName, name);
    FreeMapExtras();
    sprintf(fileName, ".\\maps\\%s", name);
    handle = open(fileName, _O_BINARY);
    if (handle == -1)
        return EDIT_MAP_FILE_ERROR;
    read(handle, &mapHeader, sizeof(mapHeader));
    gEditManager->InitializeMap(false, mapHeader.width, mapHeader.height);
    gEditMapHeader = mapHeader;
    strcpy(name, tmpName);
    sprintf(gMapFileName, name);
    gMap.Read(handle, true);
    read(handle, ignored, EDIT_MAP_TOWN_RECORDS * sizeof(EditMapRecord));
    if (gEditMapHeader.magic == MAP_HEADER_MAGIC_BASE_GAME)
        read(handle, ignored, EDIT_MAP_TOWN_RECORDS * sizeof(EditMapRecord));
    else
        read(handle, ignored, EDIT_MAP_MINE_RECORDS * sizeof(EditMapRecord));
    gEditMapHeader.magic = MAP_HEADER_MAGIC_EXPANSION_GAME;
    read(handle, ignored, 1);
    read(handle, gRumourExtras, gEditMapHeader.rumourCount * sizeof(gRumourExtras[0]));
    read(handle, gTimeEventExtras, gEditMapHeader.timeEventCount * sizeof(gTimeEventExtras[0]));
    READ_FILE_VALUE(handle, m_extraCount);
    for (i = EDIT_MANAGER_FIRST_EXTRA; i < m_extraCount; i++) {
        READ_FILE_VALUE(handle, m_extraSizes[i]);
        m_extras[i] = new char[m_extraSizes[i]];
        read(handle, m_extras[i], m_extraSizes[i]);
    }
    READ_FILE_VALUE(handle, gNextObjectLink);
    close(handle);
    gEditManager->SaveUndo();
    return EDIT_MAP_FILE_OK;
}


b32 PickMap(FileRequesterMode mode) {
    fileRequester* requester;
    char pattern[EDIT_FILE_PATTERN_SIZE];
    b32 picked;
    tag_message msg;
    i32 button;
    char ext[EDIT_FILE_PATTERN_SIZE];

    picked = false;
    if (gEditManager && gEditManager->m_window) {
        msg.type = MESSAGE_WIDGET;
        msg.payload.widget.command = WIDGET_COMMAND_CLEAR_FLAGS;
        msg.payload.widget.data.value = H2EnumIndex(WIDGET_FLAG_ENABLED);
        msg.payload.widget.id = EDIT_CONTROL_SCROLL_UP;
        gEditManager->m_window->BroadcastMessage(msg);
        msg.payload.widget.id = EDIT_CONTROL_SCROLL_DOWN;
        gEditManager->m_window->BroadcastMessage(msg);
    }
    sprintf(pattern, "*.%s", "M*2");
    sprintf(ext, ".%s", "MP2");
    requester = new fileRequester(EDIT_FILE_REQUESTER_X, EDIT_FILE_REQUESTER_Y,
                                  mode, pattern, ".\\MAPS\\", ext);
    button = gpExec->DoDialog(requester);
    if (button == FILE_REQUESTER_OK) {
        picked = true;
        strcpy(gMapFileName, gLastFilename);
    }
    delete requester;
    if (gEditManager && gEditManager->m_window) {
        msg.type = MESSAGE_WIDGET;
        msg.payload.widget.command = WIDGET_COMMAND_SET_FLAGS;
        msg.payload.widget.data.value = H2EnumIndex(WIDGET_FLAG_ENABLED);
        msg.payload.widget.id = EDIT_CONTROL_SCROLL_UP;
        gEditManager->m_window->BroadcastMessage(msg);
        msg.payload.widget.id = EDIT_CONTROL_SCROLL_DOWN;
        gEditManager->m_window->BroadcastMessage(msg);
    }
    return picked;
}

void editManager::ClearErrors(void) {
    for (; gEditErrorCount > 0; gEditErrorCount--)
        delete[] gEditErrors[gEditErrorCount - 1];
    gEditErrorCount = 0;
}


void editManager::ShowErrors(void) {
    i32 oldDebugLevel;
    i32 i;

    oldDebugLevel = giDebugLevel;
    if (gEditErrorCount > 0) {
        for (i = 0; i < gEditErrorCount; i++) {
            sprintf(gText, localization::Tr("editor.check.log"), gEditErrors[i]);
            LogStr(gText);
        }
        giDebugLevel = oldDebugLevel;
        for (i = 0; i < gEditErrorCount; i++) {
            sprintf(gText, localization::Tr("editor.check.next"), gEditErrors[i]);
            NormalDialog(gText, NORMAL_DIALOG_CONFIRM);
            if (gpWindowManager->m_dialogResult == NORMAL_DIALOG_NO)
                break;
        }
    }
}

void editManager::AddError(const char* text) {
    i32 length;

    if (gEditErrorCount < EDIT_MANAGER_ERROR_CAPACITY) {
        length = strlen(text) + 1;
        gEditErrors[gEditErrorCount] = new char[length];
        strcpy(gEditErrors[gEditErrorCount], text);
        gEditErrorCount++;
    }
}


void editManager::ClearArea(i32 x, i32 y, i32 width, i32 height, i32 mask [[maybe_unused]],
                            b32 allLayers, b32 filtered) {
    mapCellExtra* part;
    u16 nextIndex;
    i32 i;
    i32 j;
    i32 pass [[maybe_unused]];
    i32 oy [[maybe_unused]];
    mapCell* cell;

    gLinesRemoved = false;
    if (x < 0)
        x = 0;
    if (x + width > MAP_WIDTH)
        width = MAP_WIDTH - x;
    if (y < 0)
        y = 0;
    if (y + height > MAP_HEIGHT)
        height = MAP_HEIGHT - y;
    for (i = x; i < x + width; i++) {
        for (j = y; j < y + height; j++) {
            cell = gMap.CellAt(i, j);
            while (cell->m_objectIndex != MAPCELL_SPRITE_NONE
                   && (!cell->m_objectShadow || cell->m_objectHighLayer || allLayers)
                   && (!filtered || gClearTilesets[H2EnumIndex(cell->m_objectTileset)]))
                RemoveLinkedObject(cell->m_objectLink);
            if (cell->m_extraIndex
                && gMap.Extra(cell->m_extraIndex)->objectIndex != MAPCELL_SPRITE_NONE)
                part = gMap.Extra(cell->m_extraIndex);
            else
                part = NULL;
            while (part) {
                nextIndex = part->nextIndex;
                if ((!part->objectShadow || part->objectHighLayer || allLayers)
                    && (!filtered || gClearTilesets[H2EnumIndex(part->objectTileset)]))
                    RemoveLinkedObject(part->objectLink);
                if (nextIndex && gMap.Extra(nextIndex)->objectIndex != MAPCELL_SPRITE_NONE)
                    part = gMap.Extra(nextIndex);
                else
                    part = NULL;
            }
            if (allLayers) {
                while (cell->m_overlayLink)
                    RemoveLinkedObject(cell->m_overlayLink);
            }
        }
    }
    if (gLinesRemoved)
        RedrawLines(x, y, x + width - 1, y + height - 1);
}


void editManager::RemoveLinkedObject(i32 link) {
    i32 idx;
    b32 changed;
    mapCellExtra* extra;
    i32 x;
    i32 y;
    mapCell* cell;

    for (x = 0; x < MAP_WIDTH; x++) {
        for (y = 0; y < MAP_WIDTH; y++) {
            changed = true;
            while (changed) {
                changed = false;
                cell = gMap.CellAt(x, y);
                if (cell->m_objectLink == link) {
                    if (cell->m_objectTileset == TILESET_ROAD
                        || cell->m_objectTileset == TILESET_STREAM)
                        gLinesRemoved = true;
                    gMap.RemoveCellObject(x, y);
                    changed = true;
                }
                if (cell->m_overlayLink == link) {
                    gMap.RemoveCellOverlay(x, y);
                    changed = true;
                }
                idx = cell->m_extraIndex;
                while (idx) {
                    extra = gMap.extras + idx;
                    if (extra->objectLink == link) {
                        if (extra->objectTileset == TILESET_ROAD
                            || extra->objectTileset == TILESET_STREAM)
                            gLinesRemoved = true;
                        gMap.RemoveExtraObject(idx);
                        changed = true;
                        break;
                    }
                    if (extra->overlayLink == link) {
                        gMap.RemoveExtraOverlay(idx);
                        changed = true;
                        break;
                    }
                    idx = extra->nextIndex;
                }
            }
        }
    }
}
typedef enum EditMapCode {


    EDIT_MAP_CODE_LENGTH        = 4,
    EDIT_MAP_CODE_LETTER_COUNT  = 26,
    EDIT_MAP_CODE_FIRST_LETTERS = 5,
    EDIT_MAP_CODE_FIRST_LETTER  = 'V'
} EditMapCode;

typedef enum EditNewMap {


    EDIT_MAP_SERIAL_LIMIT         = 65000,
    EDIT_MAP_NAME_SERIAL_MODULUS  = 1000,

    EDIT_STATUS_WARNING_MILLISECONDS = 1500
} EditNewMap;

void editManager::ResetArea(i32 x, i32 y, i32 width, i32 height) {
    i32 i;
    i32 j;

    for (i = x; i < x + width; i++) {
        for (j = y; j < y + height; j++) {
            memset(gMap.CellAt(i, j), 0, sizeof(mapCell));
            gMap.CellAt(i, j)->m_objectLink = 0;
            gMap.CellAt(i, j)->m_overlayLink = 0;
            gMap.CellAt(i, j)->m_extraIndex = 0;
            gMap.CellAt(i, j)->m_terrainImageIndex
                = ChooseGroundTile(H2EnumIndex(TERRAIN_WATER), EDIT_SHAPE_PLAIN, true, i, j, false, 1.0f);
            gMap.CellAt(i, j)->m_objectTileset = TILESET_NONE;
            gMap.CellAt(i, j)->m_objectIndex = MAPCELL_SPRITE_NONE;
            gMap.CellAt(i, j)->m_overlayTileset = TILESET_NONE;
            gMap.CellAt(i, j)->m_overlayIndex = MAPCELL_SPRITE_NONE;
            gMap.CellAt(i, j)->m_triggerType = MAP_OBJECT_NONE;
            gMap.CellAt(i, j)->m_flags = 0;
            gMap.CellAt(i, j)->m_triggerType = MAP_OBJECT_NONE;
            gMap.CellAt(i, j)->m_objectMetadata = 0;
        }
    }
}


const char* gMapCodeLetters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";


char* MakeMapCode(i32 serial) {
    static char code[EDIT_MAP_CODE_LENGTH + 1];
    i32 unused [[maybe_unused]];

    memset(code, 0, sizeof(code));
    code[3] = gMapCodeLetters[serial % EDIT_MAP_CODE_LETTER_COUNT];
    serial -= serial % EDIT_MAP_CODE_LETTER_COUNT;
    serial /= EDIT_MAP_CODE_LETTER_COUNT;
    code[2] = gMapCodeLetters[serial % EDIT_MAP_CODE_LETTER_COUNT];
    serial -= serial % EDIT_MAP_CODE_LETTER_COUNT;
    serial /= EDIT_MAP_CODE_LETTER_COUNT;
    code[1] = gMapCodeLetters[serial % EDIT_MAP_CODE_LETTER_COUNT];
    serial -= serial % EDIT_MAP_CODE_LETTER_COUNT;
    serial /= EDIT_MAP_CODE_LETTER_COUNT;
    code[0] = serial % EDIT_MAP_CODE_FIRST_LETTERS + EDIT_MAP_CODE_FIRST_LETTER;
    return code;
}

void editManager::FreeMapExtras(void) {
    i32 i;

    for (i = EDIT_MANAGER_FIRST_EXTRA; i < m_extraCount; i++)
        delete m_extras[i];
    m_extraCount = EDIT_MANAGER_FIRST_EXTRA;
}


void editManager::InitializeMap(b32 random, i32 width, i32 height) {
    i32 unused [[maybe_unused]];

    if (width != MAP_WIDTH || height != MAP_HEIGHT) {
        MAP_HEIGHT = height;
        MAP_WIDTH = width;
        gMap.Init(MAP_HEIGHT, MAP_WIDTH);
        gUndoMap.Init(MAP_HEIGHT, MAP_WIDTH);
        ResetArea(0, 0, MAP_WIDTH, MAP_HEIGHT);
        m_viewX = m_viewY = 0;
    }
    memset(&gEditMapHeader, 0, sizeof(gEditMapHeader));
    gEditMapHeader.difficulty = DIFFICULTY_NORMAL;
    gEditMapHeader.magic = MAP_HEADER_MAGIC_EXPANSION_GAME;
    gEditMapHeader.width = width;
    gEditMapHeader.height = height;
    gEditMapHeader.rumourCount = 0;
    gEditMapHeader.timeEventCount = 0;
    gEditMapHeader.timeEventCount = 0;
    gEditMapHeader.townNameIndex = Random(0, EDITOR_TOWN_NAME_COUNT - 1);
    gEditMapHeader.nameFileOnSave = true;
    gConfig.currentMapOffset++;
    if (gConfig.firstMapOffset + gConfig.currentMapOffset > EDIT_MAP_SERIAL_LIMIT)
        gConfig.currentMapOffset = 0;
    if (random)
        sprintf(
            gEditMapHeader.name,
            localization::Tr("editor.map.random.name"),
            gConfig.currentMapOffset % EDIT_MAP_NAME_SERIAL_MODULUS
        );
    else
        sprintf(
            gEditMapHeader.name,
            localization::Tr("editor.map.unnamed"),
            gConfig.currentMapOffset % EDIT_MAP_NAME_SERIAL_MODULUS
        );
    sprintf(gEditMapHeader.description, localization::Tr("editor.map.no_description"));
    sprintf(gMapFileName, "Map_%04d.%s", gConfig.currentMapOffset, "MP2");
    WritePrefs();
    FreeMapExtras();
}


b32 editManager::CanBeCoast(i32 x, i32 y) {
    b32 shadowsOnly;
    mapCellExtra* extra;
    mapCell* cell;
    i32 extraIndex;

    if (x < 0 || x >= MAP_WIDTH || y < 0 || y >= MAP_HEIGHT)
        return false;
    cell = gMap.CellAt(x, y);
    if (!(cell->m_triggerType & MAP_TRIGGER_ACTION_FLAG) && cell->m_triggerType != MAP_OBJECT_CASTLE
        && cell->m_triggerType != MAP_OBJECT_RANDOM_TOWN && cell->m_triggerType != MAP_OBJECT_RANDOM_CASTLE) {
        if (cell->m_objectIndex != MAPCELL_SPRITE_NONE) {
            shadowsOnly = false;
            if (cell->m_objectShadow) {
                shadowsOnly = true;
                extraIndex = cell->m_extraIndex;
                while (extraIndex) {
                    extra = gMap.Extra(extraIndex);
                    if (extra->objectIndex != MAPCELL_SPRITE_NONE && !extra->objectShadow)
                        shadowsOnly = false;
                    extraIndex = extra->nextIndex;
                }
            }
            if (!shadowsOnly)
                return false;
        }
        return true;
    }
    return false;
}


void editManager::SetCoast(i32 x, i32 y) {
    mapCell* cell;

    cell = gMap.CellAt(x, y);
    if (CELL_TERRAIN(cell) != TERRAIN_WATER)
        return;
    switch (giGroundShape[cell->m_terrainImageIndex]) {
        case EDIT_SHAPE_PLAIN:
        case EDIT_SHAPE_DECORATED_FIRST:
        case EDIT_SHAPE_DECORATED_SECOND:
        case EDIT_SHAPE_DECORATED_THIRD:
        case EDIT_SHAPE_DECORATED_FOURTH:
            return;
        case EDIT_SHAPE_NORTH_EDGE:
        case EDIT_SHAPE_NORTH_EDGE_ALT:
            if (cell->m_flags & H2EnumIndex(MAP_CELL_FLIP_VERTICAL)) {
                if (y < MAP_HEIGHT - 1 && CanBeCoast(x, y + 1))
                    gMap.CellAt(x, y + 1)->m_triggerType = MAP_OBJECT_COAST;
            } else {
                if (y > 0 && CanBeCoast(x, y - 1))
                    gMap.CellAt(x, y - 1)->m_triggerType = MAP_OBJECT_COAST;
            }
            break;
        case EDIT_SHAPE_NORTH_EAST_CORNER:
            if ((cell->m_flags & H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL))
                == H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL)) {
                if (y < MAP_HEIGHT - 1 && CanBeCoast(x, y + 1))
                    gMap.CellAt(x, y + 1)->m_triggerType = MAP_OBJECT_COAST;
                if (x > 0 && CanBeCoast(x - 1, y))
                    gMap.CellAt(x - 1, y)->m_triggerType = MAP_OBJECT_COAST;
                if (y < MAP_HEIGHT - 1 && x > 0 && CanBeCoast(x - 1, y + 1))
                    gMap.CellAt(x - 1, y + 1)->m_triggerType = MAP_OBJECT_COAST;
            } else if (cell->m_flags & H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL)) {
                if (y > 0 && CanBeCoast(x, y - 1))
                    gMap.CellAt(x, y - 1)->m_triggerType = MAP_OBJECT_COAST;
                if (x > 0 && CanBeCoast(x - 1, y))
                    gMap.CellAt(x - 1, y)->m_triggerType = MAP_OBJECT_COAST;
                if (y > 0 && x > 0 && CanBeCoast(x - 1, y - 1))
                    gMap.CellAt(x - 1, y - 1)->m_triggerType = MAP_OBJECT_COAST;
            } else if (cell->m_flags & H2EnumIndex(MAP_CELL_FLIP_VERTICAL)) {
                if (y < MAP_HEIGHT - 1 && CanBeCoast(x, y + 1))
                    gMap.CellAt(x, y + 1)->m_triggerType = MAP_OBJECT_COAST;
                if (x < MAP_WIDTH - 1 && CanBeCoast(x + 1, y))
                    gMap.CellAt(x + 1, y)->m_triggerType = MAP_OBJECT_COAST;
                if (y < MAP_HEIGHT - 1 && x < MAP_WIDTH - 1 && CanBeCoast(x + 1, y + 1))
                    gMap.CellAt(x + 1, y + 1)->m_triggerType = MAP_OBJECT_COAST;
            } else {
                if (y > 0 && CanBeCoast(x, y - 1))
                    gMap.CellAt(x, y - 1)->m_triggerType = MAP_OBJECT_COAST;
                if (x < MAP_WIDTH - 1 && CanBeCoast(x + 1, y))
                    gMap.CellAt(x + 1, y)->m_triggerType = MAP_OBJECT_COAST;
                if (y > 0 && x < MAP_WIDTH - 1 && CanBeCoast(x + 1, y - 1))
                    gMap.CellAt(x + 1, y - 1)->m_triggerType = MAP_OBJECT_COAST;
            }
            break;
        case EDIT_SHAPE_EAST_EDGE:
        case EDIT_SHAPE_EAST_EDGE_ALT:
            if (cell->m_flags & H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL)) {
                if (x > 0 && CanBeCoast(x - 1, y))
                    gMap.CellAt(x - 1, y)->m_triggerType = MAP_OBJECT_COAST;
            } else {
                if (x < MAP_WIDTH - 1 && CanBeCoast(x + 1, y))
                    gMap.CellAt(x + 1, y)->m_triggerType = MAP_OBJECT_COAST;
            }
            break;
        case EDIT_SHAPE_NORTH_EAST_INNER:
            if ((cell->m_flags & H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL))
                == H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL)) {
                if (y < MAP_HEIGHT - 1 && x > 0 && CanBeCoast(x - 1, y + 1))
                    gMap.CellAt(x - 1, y + 1)->m_triggerType = MAP_OBJECT_COAST;
            } else if (cell->m_flags & H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL)) {
                if (y > 0 && x > 0 && CanBeCoast(x - 1, y - 1))
                    gMap.CellAt(x - 1, y - 1)->m_triggerType = MAP_OBJECT_COAST;
            } else if (cell->m_flags & H2EnumIndex(MAP_CELL_FLIP_VERTICAL)) {
                if (y < MAP_HEIGHT - 1 && x < MAP_WIDTH - 1 && CanBeCoast(x + 1, y + 1))
                    gMap.CellAt(x + 1, y + 1)->m_triggerType = MAP_OBJECT_COAST;
            } else {
                if (y > 0 && x < MAP_WIDTH - 1 && CanBeCoast(x + 1, y - 1))
                    gMap.CellAt(x + 1, y - 1)->m_triggerType = MAP_OBJECT_COAST;
            }
            break;
    }
}


void ShowStatusWarning(const char* text) {
    if (gGeneratingRandomMap)
        return;
    ShowStatusText(text);
    MessageBeep(MB_OK);
    gStatusTextClearTime = KBTickCount() + EDIT_STATUS_WARNING_MILLISECONDS;
}


i32 gGroundVariantChance[H2EnumIndex(TERRAIN_COUNT)] = {0, 5, 8, 8, 8, 6, 4, 8, 7};


b32 gGroundTilesIndexed;
u16 gGroundTiles[H2EnumIndex(TERRAIN_COUNT)][EDIT_SHAPE_COUNT][EDIT_GROUND_VARIANTS][EDIT_GROUND_TILES_PER_SHAPE];
u16 gGroundTileCounts[H2EnumIndex(TERRAIN_COUNT)][EDIT_SHAPE_COUNT][EDIT_GROUND_VARIANTS];
i32 gGroundTileCount;
i32 gGroundTileChoice;

i32 ChooseGroundTile(i32 terrain, i32 shape, b32 vary, i32 x, i32 y, b32 force, float chance) {
    i32 variant;
    i32 shapeIndex;
    i32 terrainIndex;
    i32 tile;

    variant = EDIT_GROUND_PLAIN;
    if (!gGroundTilesIndexed) {
        gGroundTilesIndexed = true;
        for (terrainIndex = 0; terrainIndex < H2EnumIndex(TERRAIN_COUNT); terrainIndex++)
            for (shapeIndex = 0; shapeIndex < EDIT_SHAPE_COUNT; shapeIndex++)
                for (variant = 0; variant < EDIT_GROUND_VARIANTS; variant++)
                    gGroundTileCounts[terrainIndex][shapeIndex][variant] = 0;
        for (tile = 0; tile < GROUND_TILE_IMAGE_COUNT; tile++) {
            variant = (giGroundShape[tile] & GROUND_SHAPE_VARIED) != 0;
            gGroundTiles[H2EnumIndex(giGroundToTerrain[tile])][giGroundShape[tile] & EDIT_SHAPE_MASK][variant]
                        [gGroundTileCounts[H2EnumIndex(giGroundToTerrain[tile])][giGroundShape[tile] & EDIT_SHAPE_MASK]
                                          [variant]]
                = tile;
            gGroundTileCounts[H2EnumIndex(giGroundToTerrain[tile])][giGroundShape[tile] & EDIT_SHAPE_MASK][variant]++;
        }
    }
    if (vary) {
        if (shape & GROUND_SHAPE_VARIED) {
            variant = EDIT_GROUND_VARIED;
        } else if ((gGroundVariantChance[terrain] && force)
                   || (Random(0, 100) < gGroundVariantChance[terrain] * chance
                       && gGroundTileCounts[terrain][shape & EDIT_SHAPE_MASK][EDIT_GROUND_VARIED]
                              > 0)) {
            if ((x <= 0
                 || !(giGroundShape[gMap.CellAt(x - 1, y)->m_terrainImageIndex] & GROUND_SHAPE_VARIED))
                && (x >= MAP_WIDTH - 2
                    || !(giGroundShape[gMap.CellAt(x + 1, y)->m_terrainImageIndex] & GROUND_SHAPE_VARIED))
                && (y <= 0
                    || !(giGroundShape[gMap.CellAt(x, y - 1)->m_terrainImageIndex] & GROUND_SHAPE_VARIED))
                && (y >= MAP_HEIGHT - 2
                    || !(giGroundShape[gMap.CellAt(x, y + 1)->m_terrainImageIndex] & GROUND_SHAPE_VARIED)))
                variant = EDIT_GROUND_VARIED;
        }
        gGroundTileCount = gGroundTileCounts[terrain][shape & EDIT_SHAPE_MASK][variant];
        if (gGroundTileCount) {
            if (gGroundTileCount > 1)
                gGroundTileChoice = Random(0, gGroundTileCount - 1);
            else
                gGroundTileChoice = 0;
        } else {
            gGroundTileChoice = 0;
            variant = EDIT_GROUND_PLAIN;
        }
        return gGroundTiles[terrain][shape][variant][gGroundTileChoice];
    }
    return gGroundTiles[terrain][shape][EDIT_GROUND_PLAIN][0];
}

typedef enum EditBlendTerrain {


    EDIT_BLEND_MAX_PASSES  = 8,
    EDIT_BLEND_WATER_SIDES = 3
} EditBlendTerrain;


i32 InMapArea(i32 x, i32 y) {
    return x >= EDIT_VIEW_LEFT && x < EDIT_VIEW_PIXELS && y >= EDIT_VIEW_TOP
        && y < EDIT_VIEW_PIXELS;
}


void editManager::BlendTerrain(i32 terrain [[maybe_unused]], b32 generating [[maybe_unused]], b32 fromUndo,
                               b32 skipBorders, b32 skipFill) {
    b32 otherUp;
    b32 otherUpRight;
    mapCell* cell;
    i32 thisTerrain;
    b32 otherDown;
    i32 passes;
    i32 bestCount;
    b32 waterDownLeft;
    b32 sameLeft;
    b32 waterRight;
    b32 sameUp;
    b32 sameDownLeft;
    b32 waterDownRight;
    i32 k;
    i32 y;
    b32 sameDown;
    i32 x;
    b32 sameDownRight;
    b32 otherRight;
    b32 waterUp;
    b32 waterUpLeft;
    i32 unused [[maybe_unused]];
    b32 repeat;
    u8 terrainCounts[H2EnumIndex(TERRAIN_COUNT)];
    b32 waterUpRight;
    i32 newTerrain;
    b32 sameUpLeft;
    b32 otherDownLeft;
    b32 sameRight;
    b32 sameUpRight;
    b32 otherDownRight;
    b32 waterLeft;
    b32 otherUpLeft;
    b32 waterDown;
    b32 otherLeft;

    fromUndo = false;
    newTerrain = 0;
    passes = 0;
    if (skipFill)
        goto borders;
    LogStr("PB 1");
    repeat = true;
    while (repeat && passes < EDIT_BLEND_MAX_PASSES) {
        repeat = false;
        passes++;
        for (y = 0; y < MAP_HEIGHT; y++) {
            for (x = 0; x < MAP_WIDTH; x++) {
                thisTerrain = H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x, y)));

                if (1) {
                    waterUp = waterDown = waterRight = waterLeft = sameUp = sameDown = sameRight = sameLeft
                        = sameUpLeft = sameUpRight = sameDownLeft = sameDownRight = 0;
                    if (!y || H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x, y - 1))) == thisTerrain)
                        sameUp = true;
                    else if (!CELL_TERRAIN(gMap.CellAt(x, y - 1)))
                        waterUp = true;
                    if (y == MAP_HEIGHT - 1 || H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x, y + 1))) == thisTerrain)
                        sameDown = true;
                    else if (!CELL_TERRAIN(gMap.CellAt(x, y + 1)))
                        waterDown = true;
                    if (x == MAP_WIDTH - 1 || H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x + 1, y))) == thisTerrain)
                        sameRight = true;
                    else if (!CELL_TERRAIN(gMap.CellAt(x + 1, y)))
                        waterRight = true;
                    if (!x || H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x - 1, y))) == thisTerrain)
                        sameLeft = true;
                    else if (!CELL_TERRAIN(gMap.CellAt(x - 1, y)))
                        waterLeft = true;
                    if (!x || !y || H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x - 1, y - 1))) == thisTerrain)
                        sameUpLeft = true;
                    if (!x || y == MAP_HEIGHT - 1 || H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x - 1, y + 1))) == thisTerrain)
                        sameDownLeft = true;
                    if (x == MAP_WIDTH - 1 || !y || H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x + 1, y - 1))) == thisTerrain)
                        sameUpRight = true;
                    if (x == MAP_WIDTH - 1 || y == MAP_HEIGHT - 1
                        || H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x + 1, y + 1))) == thisTerrain)
                        sameDownRight = true;
                    if (!sameUp || !sameDown || !sameRight || !sameLeft) {
                        memset(terrainCounts, 0, sizeof(terrainCounts));
                        if (x < MAP_WIDTH - 1)
                            terrainCounts[H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x + 1, y)))]++;
                        if (x > 0)
                            terrainCounts[H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x - 1, y)))]++;
                        if (y < MAP_HEIGHT - 1)
                            terrainCounts[H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x, y + 1)))]++;
                        if (y > 0)
                            terrainCounts[H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x, y - 1)))]++;
                        newTerrain = 0;
                        bestCount = 0;
                        for (k = 0; k < H2EnumIndex(TERRAIN_COUNT); k++) {
                            if (terrainCounts[k] >= bestCount && k != thisTerrain) {
                                newTerrain = k;
                                bestCount = terrainCounts[k];
                            }
                        }
                    }
                    if ((!sameUp || !sameLeft) && (!sameUp || !sameRight) && (!sameDown || !sameLeft)
                        && (!sameDown || !sameRight)) {
                        if (thisTerrain && x > 0 && y > 0 && x < MAP_WIDTH - 1 && y < MAP_HEIGHT - 1) {
                            if (waterUp + waterDown + waterRight + waterLeft
                                >= EDIT_BLEND_WATER_SIDES) {
                                SetCellGround(x, y, H2EnumIndex(TERRAIN_WATER), EDIT_SHAPE_PLAIN);
                            } else if (waterUp && waterRight) {
                                newTerrain = H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x - 1, y + 1)));
                                SetCellGround(x, y, newTerrain, EDIT_SHAPE_PLAIN);
                                SetCellGround(x, y + 1, newTerrain, EDIT_SHAPE_PLAIN);
                                SetCellGround(x - 1, y, newTerrain, EDIT_SHAPE_PLAIN);
                            } else if (waterUp && waterLeft) {
                                newTerrain = H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x + 1, y + 1)));
                                SetCellGround(x, y, newTerrain, EDIT_SHAPE_PLAIN);
                                SetCellGround(x, y + 1, newTerrain, EDIT_SHAPE_PLAIN);
                                SetCellGround(x + 1, y, newTerrain, EDIT_SHAPE_PLAIN);
                            } else if (waterDown && waterRight) {
                                newTerrain = H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x - 1, y - 1)));
                                SetCellGround(x, y, newTerrain, EDIT_SHAPE_PLAIN);
                                SetCellGround(x, y - 1, newTerrain, EDIT_SHAPE_PLAIN);
                                SetCellGround(x - 1, y, newTerrain, EDIT_SHAPE_PLAIN);
                            } else if (waterDown && waterLeft) {
                                newTerrain = H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x + 1, y - 1)));
                                SetCellGround(x, y, newTerrain, EDIT_SHAPE_PLAIN);
                                SetCellGround(x, y - 1, newTerrain, EDIT_SHAPE_PLAIN);
                                SetCellGround(x + 1, y, newTerrain, EDIT_SHAPE_PLAIN);
                            } else if (thisTerrain != H2EnumIndex(TERRAIN_DIRT)) {
                                SetCellGround(x, y, newTerrain, EDIT_SHAPE_PLAIN);
                            }
                        } else if (!thisTerrain || terrainCounts[newTerrain] >= terrainCounts[thisTerrain]) {
                            SetCellGround(x, y, newTerrain, EDIT_SHAPE_PLAIN);
                        }
                        repeat = true;
                    }
                    if (!thisTerrain && x > 0 && y > 0 && x < MAP_WIDTH - 1 && y < MAP_HEIGHT - 1 && sameUp && sameDown
                        && sameLeft && sameRight) {
                        if (CELL_TERRAIN(gMap.CellAt(x - 1, y - 1)) && CELL_TERRAIN(gMap.CellAt(x + 1, y + 1))) {
                            SetCellGround(x, y, H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x - 1, y - 1))), EDIT_SHAPE_PLAIN);
                            SetCellGround(x - 1, y, H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x - 1, y - 1))), EDIT_SHAPE_PLAIN);
                            SetCellGround(x, y - 1, H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x - 1, y - 1))), EDIT_SHAPE_PLAIN);
                            repeat = true;
                        }
                        if (CELL_TERRAIN(gMap.CellAt(x + 1, y - 1)) && CELL_TERRAIN(gMap.CellAt(x - 1, y + 1))) {
                            SetCellGround(x, y, H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x + 1, y - 1))), EDIT_SHAPE_PLAIN);
                            SetCellGround(x + 1, y, H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x + 1, y - 1))), EDIT_SHAPE_PLAIN);
                            SetCellGround(x, y - 1, H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x + 1, y - 1))), EDIT_SHAPE_PLAIN);
                            repeat = true;
                        }
                    } else if (!thisTerrain && x > 0 && y > 0 && x < MAP_WIDTH - 1 && y < MAP_HEIGHT - 1 && sameUp
                               && sameDown) {
                        if (!sameRight && !sameUpLeft) {
                            SetCellGround(x, y - 1, newTerrain, EDIT_SHAPE_PLAIN);
                            SetCellGround(x, y, newTerrain, EDIT_SHAPE_PLAIN);
                            repeat = true;
                        }
                        if (!sameRight && !sameDownLeft) {
                            SetCellGround(x, y + 1, newTerrain, EDIT_SHAPE_PLAIN);
                            SetCellGround(x, y, newTerrain, EDIT_SHAPE_PLAIN);
                            repeat = true;
                        }
                        if (!sameLeft && !sameUpRight) {
                            SetCellGround(x, y - 1, newTerrain, EDIT_SHAPE_PLAIN);
                            SetCellGround(x, y, newTerrain, EDIT_SHAPE_PLAIN);
                            repeat = true;
                        }
                        if (!sameLeft && !sameDownRight) {
                            SetCellGround(x, y + 1, newTerrain, EDIT_SHAPE_PLAIN);
                            SetCellGround(x, y, newTerrain, EDIT_SHAPE_PLAIN);
                            repeat = true;
                        }
                    } else if (!thisTerrain && x > 0 && y > 0 && x < MAP_WIDTH - 1 && y < MAP_HEIGHT - 1 && sameRight
                               && sameLeft) {
                        if (!sameUp && !sameDownLeft) {
                            SetCellGround(x - 1, y, newTerrain, EDIT_SHAPE_PLAIN);
                            SetCellGround(x, y, newTerrain, EDIT_SHAPE_PLAIN);
                            repeat = true;
                        }
                        if (!sameUp && !sameDownRight) {
                            SetCellGround(x + 1, y, newTerrain, EDIT_SHAPE_PLAIN);
                            SetCellGround(x, y, newTerrain, EDIT_SHAPE_PLAIN);
                            repeat = true;
                        }
                        if (!sameDown && !sameUpLeft) {
                            SetCellGround(x - 1, y, newTerrain, EDIT_SHAPE_PLAIN);
                            SetCellGround(x, y, newTerrain, EDIT_SHAPE_PLAIN);
                            repeat = true;
                        }
                        if (!sameDown && !sameUpRight) {
                            SetCellGround(x + 1, y, newTerrain, EDIT_SHAPE_PLAIN);
                            SetCellGround(x, y, newTerrain, EDIT_SHAPE_PLAIN);
                            repeat = true;
                        }
                    }
                }
            }
        }
    }
    LogStr("PB 2");
borders:
    LogStr("PB 3");
    if (skipBorders)
        return;
    for (y = 0; y < MAP_HEIGHT; y++) {
        for (x = 0; x < MAP_WIDTH; x++) {
            cell = gMap.CellAt(x, y);
            thisTerrain = H2EnumIndex(CELL_TERRAIN(cell));
            if (thisTerrain == H2EnumIndex(TERRAIN_BEACH))
                continue;
            otherUpRight = otherUpLeft = otherDownRight = otherDownLeft = otherUp = otherDown = otherRight
                = otherLeft = 0;
            waterUpRight = waterUpLeft = waterDownRight = waterDownLeft = waterUp = waterDown = waterRight
                = waterLeft = 0;
            if (thisTerrain != H2EnumIndex(TERRAIN_DIRT)) {
                if (y > 0 && H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x, y - 1))) != thisTerrain && CELL_TERRAIN(gMap.CellAt(x, y - 1)))
                    otherUp = true;
                if (y < MAP_HEIGHT - 1 && H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x, y + 1))) != thisTerrain
                    && CELL_TERRAIN(gMap.CellAt(x, y + 1)))
                    otherDown = true;
                if (x < MAP_WIDTH - 1 && H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x + 1, y))) != thisTerrain
                    && CELL_TERRAIN(gMap.CellAt(x + 1, y)))
                    otherRight = true;
                if (x > 0 && H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x - 1, y))) != thisTerrain && CELL_TERRAIN(gMap.CellAt(x - 1, y)))
                    otherLeft = true;
                if (x > 0 && y > 0 && H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x - 1, y - 1))) != thisTerrain
                    && CELL_TERRAIN(gMap.CellAt(x - 1, y - 1)))
                    otherUpLeft = true;
                if (x > 0 && y < MAP_HEIGHT - 1 && H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x - 1, y + 1))) != thisTerrain
                    && CELL_TERRAIN(gMap.CellAt(x - 1, y + 1)))
                    otherDownLeft = true;
                if (x < MAP_WIDTH - 1 && y < MAP_HEIGHT - 1 && H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x + 1, y + 1))) != thisTerrain
                    && CELL_TERRAIN(gMap.CellAt(x + 1, y + 1)))
                    otherDownRight = true;
                if (x < MAP_WIDTH - 1 && y > 0 && H2EnumIndex(CELL_TERRAIN(gMap.CellAt(x + 1, y - 1))) != thisTerrain
                    && CELL_TERRAIN(gMap.CellAt(x + 1, y - 1)))
                    otherUpRight = true;
            }
            if (thisTerrain != H2EnumIndex(TERRAIN_WATER) && thisTerrain != H2EnumIndex(TERRAIN_BEACH)) {
                if (y > 0
                    && (!CELL_TERRAIN(gMap.CellAt(x, y - 1)) || CELL_TERRAIN(gMap.CellAt(x, y - 1)) == TERRAIN_BEACH))
                    waterUp = true;
                if (y < MAP_HEIGHT - 1
                    && (!CELL_TERRAIN(gMap.CellAt(x, y + 1)) || CELL_TERRAIN(gMap.CellAt(x, y + 1)) == TERRAIN_BEACH))
                    waterDown = true;
                if (x < MAP_WIDTH - 1
                    && (!CELL_TERRAIN(gMap.CellAt(x + 1, y)) || CELL_TERRAIN(gMap.CellAt(x + 1, y)) == TERRAIN_BEACH))
                    waterRight = true;
                if (x > 0
                    && (!CELL_TERRAIN(gMap.CellAt(x - 1, y)) || CELL_TERRAIN(gMap.CellAt(x - 1, y)) == TERRAIN_BEACH))
                    waterLeft = true;
                if (x > 0 && y > 0
                    && (!CELL_TERRAIN(gMap.CellAt(x - 1, y - 1))
                        || CELL_TERRAIN(gMap.CellAt(x - 1, y - 1)) == TERRAIN_BEACH))
                    waterUpLeft = true;
                if (x > 0 && y < MAP_HEIGHT - 1
                    && (!CELL_TERRAIN(gMap.CellAt(x - 1, y + 1))
                        || CELL_TERRAIN(gMap.CellAt(x - 1, y + 1)) == TERRAIN_BEACH))
                    waterDownLeft = true;
                if (x < MAP_WIDTH - 1 && y < MAP_HEIGHT - 1
                    && (!CELL_TERRAIN(gMap.CellAt(x + 1, y + 1))
                        || CELL_TERRAIN(gMap.CellAt(x + 1, y + 1)) == TERRAIN_BEACH))
                    waterDownRight = true;
                if (x < MAP_WIDTH - 1 && y > 0
                    && (!CELL_TERRAIN(gMap.CellAt(x + 1, y - 1))
                        || CELL_TERRAIN(gMap.CellAt(x + 1, y - 1)) == TERRAIN_BEACH))
                    waterUpRight = true;
            }
            cell->m_flags &= ~H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL);
            if ((otherUpRight || otherUpLeft || otherDownRight || otherDownLeft || otherUp || otherDown || otherRight
                 || otherLeft)
                && (waterUpRight || waterUpLeft || waterDownRight || waterDownLeft || waterUp || waterDown
                    || waterRight || waterLeft)
                && (otherUp || otherDown || otherRight || otherLeft || waterUp || waterDown || waterRight
                    || waterLeft)) {
                if (waterUp) {
                    if (waterLeft) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_CORNER);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL);
                    } else if (waterRight) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_CORNER);
                    } else if (otherRight) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_EDGE_BORDER);
                    } else if (otherLeft) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_EDGE_BORDER);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL);
                    } else {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_NORTH_EDGE);
                    }
                } else if (waterDown) {
                    if (waterLeft) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_CORNER);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL);
                    } else if (waterRight) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_CORNER);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL);
                    } else if (otherRight) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_EDGE_BORDER);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL);
                    } else if (otherLeft) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_EDGE_BORDER);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL);
                    } else {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_NORTH_EDGE);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL);
                    }
                } else if (waterRight) {
                    if (otherUp) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_SIDE_BORDER);
                    } else if (otherDown) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_SIDE_BORDER);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL);
                    } else {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_EAST_EDGE);
                    }
                } else if (waterLeft) {
                    if (otherUp) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_SIDE_BORDER);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL);
                    } else if (otherDown) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_SIDE_BORDER);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL);
                    } else {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_EAST_EDGE);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL);
                    }
                } else if (otherUp) {
                    if (otherLeft) {
                        if (waterDownLeft) {
                            SetCellGround(x, y, thisTerrain, EDIT_SHAPE_CORNER_SHORE_FAR);
                            cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL);
                        } else if (waterUpRight) {
                            SetCellGround(x, y, thisTerrain, EDIT_SHAPE_CORNER_SHORE_NEAR);
                            cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL);
                        } else {
                            SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EAST_CORNER);
                            cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL);
                        }
                    } else if (otherRight) {
                        if (waterDownRight)
                            SetCellGround(x, y, thisTerrain, EDIT_SHAPE_CORNER_SHORE_FAR);
                        else if (waterUpLeft)
                            SetCellGround(x, y, thisTerrain, EDIT_SHAPE_CORNER_SHORE_NEAR);
                        else
                            SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EAST_CORNER);
                    } else if (waterUpRight) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EDGE_SHORE);
                    } else if (waterUpLeft) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EDGE_SHORE);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL);
                    } else {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EDGE);
                    }
                } else if (otherDown) {
                    if (otherLeft) {
                        if (waterUpLeft) {
                            SetCellGround(x, y, thisTerrain, EDIT_SHAPE_CORNER_SHORE_FAR);
                            cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL);
                        } else if (waterDownRight) {
                            SetCellGround(x, y, thisTerrain, EDIT_SHAPE_CORNER_SHORE_NEAR);
                            cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL);
                        } else {
                            SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EAST_CORNER);
                            cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL);
                        }
                    } else if (otherRight) {
                        if (waterUpRight) {
                            SetCellGround(x, y, thisTerrain, EDIT_SHAPE_CORNER_SHORE_FAR);
                            cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL);
                        } else if (waterDownLeft) {
                            SetCellGround(x, y, thisTerrain, EDIT_SHAPE_CORNER_SHORE_NEAR);
                            cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL);
                        } else {
                            SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EAST_CORNER);
                            cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL);
                        }
                    } else if (waterDownRight) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EDGE_SHORE);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL);
                    } else if (waterDownLeft) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EDGE_SHORE);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL);
                    } else {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EDGE);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL);
                    }
                } else if (otherRight) {
                    if (waterUpRight) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_EAST_EDGE_SHORE);
                    } else if (waterDownRight) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_EAST_EDGE_SHORE);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL);
                    } else {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_EAST_EDGE);
                    }
                } else if (otherLeft) {
                    if (waterUpLeft) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_EAST_EDGE_SHORE);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL);
                    } else if (waterDownLeft) {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_EAST_EDGE_SHORE);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL);
                    } else {
                        SetCellGround(x, y, thisTerrain, EDIT_SHAPE_EAST_EDGE);
                        cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL);
                    }
                }
                continue;
            }
            if (waterUp) {
                if (waterLeft) {
                    SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_CORNER);
                    cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL);
                } else if (waterRight) {
                    SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_CORNER);
                } else {
                    SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_NORTH_EDGE);
                }
            } else if (waterDown) {
                if (waterLeft) {
                    SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_CORNER);
                    cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL);
                } else if (waterRight) {
                    SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_CORNER);
                    cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL);
                } else {
                    SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_NORTH_EDGE);
                    cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL);
                }
            } else if (waterLeft) {
                SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_EAST_EDGE);
                cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL);
            } else if (waterRight) {
                SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_EAST_EDGE);
            }
            if (waterUp | waterDown | waterRight | waterLeft)
                continue;
            if (otherUp) {
                if (otherLeft) {
                    SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EAST_CORNER);
                    cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL);
                } else if (otherRight) {
                    SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EAST_CORNER);
                } else {
                    SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EDGE);
                }
            } else if (otherDown) {
                if (otherLeft) {
                    SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EAST_CORNER);
                    cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL);
                } else if (otherRight) {
                    SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EAST_CORNER);
                    cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL);
                } else {
                    SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EDGE);
                    cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL);
                }
            } else if (otherLeft) {
                SetCellGround(x, y, thisTerrain, EDIT_SHAPE_EAST_EDGE);
                cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL);
            } else if (otherRight) {
                SetCellGround(x, y, thisTerrain, EDIT_SHAPE_EAST_EDGE);
            }
            if (otherUp | otherDown | otherRight | otherLeft)
                continue;
            if (waterUpLeft) {
                SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_INNER);
                cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL);
            } else if (waterDownLeft) {
                SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_INNER);
                cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL);
            } else if (waterDownRight) {
                SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_INNER);
                cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL);
            } else if (waterUpRight) {
                SetCellGround(x, y, thisTerrain, EDIT_SHAPE_SHORE_INNER);
            }
            if (waterUpLeft | waterDownLeft | waterDownRight | waterUpRight)
                continue;
            if (otherUpLeft) {
                SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EAST_INNER);
                cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL);
            } else if (otherDownLeft) {
                SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EAST_INNER);
                cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL);
            } else if (otherDownRight) {
                SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EAST_INNER);
                cell->m_flags |= H2EnumIndex(MAP_CELL_FLIP_VERTICAL);
            } else if (otherUpRight) {
                SetCellGround(x, y, thisTerrain, EDIT_SHAPE_NORTH_EAST_INNER);
            }
            if (otherUpLeft | otherDownLeft | otherDownRight | otherUpRight)
                continue;
            SetCellGround(x, y, thisTerrain, EDIT_SHAPE_PLAIN);
        }
    }
    BlendShallowWater();
    LogStr("PB 5");
}


void editManager::BlendShallowWater(void) {
    const i32 maxPass = 3;
    const u8 unset = 0x80;
    i32 shape;
    i8* shoreDistance;
    i32 limit;
    const u8 deepSea = 0x40;
    i32 band;
    i32 x;
    EditCornerCounts neighbors;
    const u8 flat = 0;
    const u8 tileUpperRight = 0x10;
    const u8 tileLowerRight = 0x11;
    const u8 tileUpperLeft = 0x12;
    const u8 tileLowerLeft = 0x13;
    mapCell* cell;
    u8* shade;
    u8* shadeCopy;
    i32 rounds;
    const u8 defaultFlip = 0;
    const u8 vFlip = 1;
    const u8 crossFlip = 2;
    const u8 twoFlips = 3;
    const u8 shore = 0x10;
    i32 y;
    b32 again;
    i8* oldDistance;

    shadeCopy = new u8[MAP_WIDTH * MAP_HEIGHT];
    shade = new u8[MAP_WIDTH * MAP_HEIGHT];
    shoreDistance = new i8[MAP_WIDTH * MAP_HEIGHT];
    oldDistance = new i8[MAP_WIDTH * MAP_HEIGHT];
    memset(shade, unset, MAP_WIDTH * MAP_HEIGHT);
    for (x = 0; x < MAP_WIDTH; x++) {
        for (y = 0; y < MAP_HEIGHT; y++) {
            cell = gMap.CellAt(x, y);
            if (!CELL_TERRAIN(cell)) {
                *(shoreDistance + x + y * MAP_WIDTH) = -1;
                switch (giGroundShape[cell->m_terrainImageIndex] & EDIT_SHAPE_MASK) {
                    case EDIT_SHAPE_NORTH_EAST_CORNER:
                    case EDIT_SHAPE_NORTH_EAST_INNER:
                        *(shade + x + y * MAP_WIDTH) =
                            (cell->m_flags & H2EnumIndex(MAP_CELL_FLIP_VERTICAL | MAP_CELL_FLIP_HORIZONTAL))
                            | shore;
                        break;
                    default:
                        *(shade + x + y * MAP_WIDTH) = flat;
                        break;
                }
            } else {
                *(shoreDistance + x + y * MAP_WIDTH) = 0;
            }
        }
    }
    for (band = 0; band <= maxPass; band++) {
        memcpy(oldDistance, shoreDistance, MAP_WIDTH * MAP_HEIGHT);
        for (x = 0; x < MAP_WIDTH; x++) {
            for (y = 0; y < MAP_HEIGHT; y++) {
                if (*(oldDistance + x + y * MAP_WIDTH) & unset) {
                    if (band == maxPass)
                        *(shade + x + y * MAP_WIDTH) = deepSea;
                    else if ((x > 0 && *(oldDistance + x - 1 + y * MAP_WIDTH) >= 0)
                             || (y > 0 && *(oldDistance + x + (y - 1) * MAP_WIDTH) >= 0)
                             || (x < MAP_WIDTH - 2 && *(oldDistance + x + 1 + y * MAP_WIDTH) >= 0)
                             || (y < MAP_HEIGHT - 2 && *(oldDistance + x + (y + 1) * MAP_WIDTH) >= 0))
                        *(shoreDistance + x + y * MAP_WIDTH) = band;
                }
            }
        }
    }
    again = true;
    rounds = 0;
    limit = MAP_WIDTH >> 1;
    while (again && rounds < limit) {
        memcpy(shadeCopy, shade, MAP_WIDTH * MAP_HEIGHT);
        again = false;
        rounds++;
        for (x = 0; x < MAP_WIDTH; x++) {
            for (y = 0; y < MAP_HEIGHT; y++) {
                cell = gMap.CellAt(x, y);
                shape = giGroundShape[cell->m_terrainImageIndex] & EDIT_SHAPE_MASK;
                if (!*(shadeCopy + x + y * MAP_WIDTH)) {
                    again = true;
                    neighbors.any = 0;
                    if (x > 0 && *(shadeCopy + x - 1 + y * MAP_WIDTH) & shore)
                        neighbors.corner[*(shadeCopy + x - 1 + y * MAP_WIDTH) & twoFlips]++;
                    if (y > 0 && *(shadeCopy + x + (y - 1) * MAP_WIDTH) & shore)
                        neighbors.corner[*(shadeCopy + x + (y - 1) * MAP_WIDTH) & twoFlips]++;
                    if (x < MAP_WIDTH - 2 && *(shadeCopy + x + 1 + y * MAP_WIDTH) & shore)
                        neighbors.corner[*(shadeCopy + x + 1 + y * MAP_WIDTH) & twoFlips]++;
                    if (y < MAP_HEIGHT - 2 && *(shadeCopy + x + (y + 1) * MAP_WIDTH) & shore)
                        neighbors.corner[*(shadeCopy + x + (y + 1) * MAP_WIDTH) & twoFlips]++;
                    if (neighbors.any) {
                        if (shape == EDIT_SHAPE_EAST_EDGE || shape == EDIT_SHAPE_EAST_EDGE_ALT) {
                            if (cell->m_flags & H2EnumIndex(MAP_CELL_FLIP_HORIZONTAL)) {
                                if (neighbors.corner[crossFlip] || neighbors.corner[twoFlips]) {
                                    if (neighbors.corner[crossFlip] > neighbors.corner[twoFlips])
                                        *(shade + x + y * MAP_WIDTH) = tileUpperLeft;
                                    else
                                        *(shade + x + y * MAP_WIDTH) = tileLowerLeft;
                                }
                            } else {
                                if (neighbors.corner[defaultFlip] || neighbors.corner[vFlip]) {
                                    if (neighbors.corner[defaultFlip] > neighbors.corner[vFlip])
                                        *(shade + x + y * MAP_WIDTH) = tileUpperRight;
                                    else
                                        *(shade + x + y * MAP_WIDTH) = tileLowerRight;
                                }
                            }
                        } else if (shape == EDIT_SHAPE_NORTH_EDGE || shape == EDIT_SHAPE_NORTH_EDGE_ALT) {
                            if (cell->m_flags & H2EnumIndex(MAP_CELL_FLIP_VERTICAL)) {
                                if (neighbors.corner[vFlip] || neighbors.corner[twoFlips]) {
                                    if (neighbors.corner[vFlip] > neighbors.corner[twoFlips])
                                        *(shade + x + y * MAP_WIDTH) = tileLowerRight;
                                    else
                                        *(shade + x + y * MAP_WIDTH) = tileLowerLeft;
                                }
                            } else {
                                if (neighbors.corner[defaultFlip] || neighbors.corner[crossFlip]) {
                                    if (neighbors.corner[defaultFlip] > neighbors.corner[crossFlip])
                                        *(shade + x + y * MAP_WIDTH) = tileUpperRight;
                                    else
                                        *(shade + x + y * MAP_WIDTH) = tileUpperLeft;
                                }
                            }
                        } else if (neighbors.corner[twoFlips]
                                   && neighbors.corner[crossFlip] <= neighbors.corner[twoFlips]
                                   && neighbors.corner[defaultFlip] <= neighbors.corner[twoFlips]
                                   && neighbors.corner[vFlip] <= neighbors.corner[twoFlips]) {
                            *(shade + x + y * MAP_WIDTH) = tileLowerLeft;
                        } else if (neighbors.corner[vFlip]
                                   && neighbors.corner[crossFlip] <= neighbors.corner[vFlip]
                                   && neighbors.corner[defaultFlip] <= neighbors.corner[vFlip]) {
                            *(shade + x + y * MAP_WIDTH) = tileLowerRight;
                        } else if (neighbors.corner[crossFlip] >= neighbors.corner[defaultFlip]) {
                            *(shade + x + y * MAP_WIDTH) = tileUpperLeft;
                        } else {
                            *(shade + x + y * MAP_WIDTH) = tileUpperRight;
                        }
                    }
                }
            }
        }
        memcpy(shadeCopy, shade, MAP_WIDTH * MAP_HEIGHT);
    }
    for (x = 0; x < MAP_WIDTH; x++) {
        for (y = 0; y < MAP_HEIGHT; y++) {
            cell = gMap.CellAt(x, y);
            shape = giGroundShape[cell->m_terrainImageIndex] & EDIT_SHAPE_MASK;
            if (*(shadeCopy + x + y * MAP_WIDTH) & shore) {
                if (shape == EDIT_SHAPE_EAST_EDGE || shape == EDIT_SHAPE_EAST_EDGE_ALT) {
                    if (*(shadeCopy + x + y * MAP_WIDTH) == tileUpperLeft
                        || *(shadeCopy + x + y * MAP_WIDTH) == tileUpperRight)
                        SetCellGround(x, y, H2EnumIndex(TERRAIN_WATER), EDIT_SHAPE_EAST_EDGE);
                    else
                        SetCellGround(x, y, H2EnumIndex(TERRAIN_WATER), EDIT_SHAPE_EAST_EDGE_ALT);
                } else if (shape == EDIT_SHAPE_NORTH_EDGE || shape == EDIT_SHAPE_NORTH_EDGE_ALT) {
                    if (*(shadeCopy + x + y * MAP_WIDTH) == tileUpperRight
                        || *(shadeCopy + x + y * MAP_WIDTH) == tileLowerRight)
                        SetCellGround(x, y, H2EnumIndex(TERRAIN_WATER), EDIT_SHAPE_NORTH_EDGE);
                    else
                        SetCellGround(x, y, H2EnumIndex(TERRAIN_WATER), EDIT_SHAPE_NORTH_EDGE_ALT);
                } else if (shape == EDIT_SHAPE_PLAIN || shape == EDIT_SHAPE_DECORATED_FIRST
                           || shape == EDIT_SHAPE_DECORATED_SECOND || shape == EDIT_SHAPE_DECORATED_THIRD
                           || shape == EDIT_SHAPE_DECORATED_FOURTH) {
                    if (*(shadeCopy + x + y * MAP_WIDTH) == tileUpperRight)
                        SetCellGround(x, y, H2EnumIndex(TERRAIN_WATER), EDIT_SHAPE_DECORATED_FIRST);
                    else if (*(shadeCopy + x + y * MAP_WIDTH) == tileLowerRight)
                        SetCellGround(x, y, H2EnumIndex(TERRAIN_WATER), EDIT_SHAPE_DECORATED_THIRD);
                    else if (*(shadeCopy + x + y * MAP_WIDTH) == tileLowerLeft)
                        SetCellGround(x, y, H2EnumIndex(TERRAIN_WATER), EDIT_SHAPE_DECORATED_FOURTH);
                    else if (*(shadeCopy + x + y * MAP_WIDTH) == tileUpperLeft)
                        SetCellGround(x, y, H2EnumIndex(TERRAIN_WATER), EDIT_SHAPE_DECORATED_SECOND);
                }
            } else if (!CELL_TERRAIN(cell)
                       && (shape == EDIT_SHAPE_PLAIN || shape == EDIT_SHAPE_DECORATED_FIRST
                           || shape == EDIT_SHAPE_DECORATED_SECOND || shape == EDIT_SHAPE_DECORATED_THIRD
                           || shape == EDIT_SHAPE_DECORATED_FOURTH)) {
                SetCellGround(x, y, H2EnumIndex(TERRAIN_WATER), EDIT_SHAPE_PLAIN);
            }
        }
    }
    delete[] shadeCopy;
    delete[] shade;
    delete[] shoreDistance;
    delete[] oldDistance;
}

typedef enum EditScreenScroll {


    EDIT_SCROLL_TICK_INTERVAL = 70,
    EDIT_SCROLL_BORDER        = 8
} EditScreenScroll;


i32 gLastScrollTime;


void editManager::ScreenScroll(MapDirection direction, b32 updatePointer) {
    i32 yOrigin;
    i32 xOrigin;

    xOrigin = m_viewX;
    yOrigin = m_viewY;
    gLastScrollTime = KBTickCount();
    switch (direction) {
        case MAP_DIRECTION_NORTH:
            yOrigin--;
            break;
        case MAP_DIRECTION_NORTH_EAST:
            xOrigin++;
            yOrigin--;
            break;
        case MAP_DIRECTION_EAST:
            xOrigin++;
            break;
        case MAP_DIRECTION_SOUTH_EAST:
            xOrigin++;
            yOrigin++;
            break;
        case MAP_DIRECTION_SOUTH:
            yOrigin++;
            break;
        case MAP_DIRECTION_SOUTH_WEST:
            xOrigin--;
            yOrigin++;
            break;
        case MAP_DIRECTION_WEST:
            xOrigin--;
            break;
        case MAP_DIRECTION_NORTH_WEST:
            xOrigin--;
            yOrigin--;
            break;
    }
    if (updatePointer)
        gpMouseManager->SetPointer(H2EnumIndex(direction) + ADVENTURE_POINTER_SCROLL_FIRST);
    if (xOrigin < 0)
        xOrigin = 0;
    if (xOrigin > MAP_WIDTH - gZoomViewCells[m_zoomLevel])
        xOrigin = MAP_WIDTH - gZoomViewCells[m_zoomLevel];
    if (yOrigin < 0)
        yOrigin = 0;
    if (yOrigin > MAP_HEIGHT - gZoomViewCells[m_zoomLevel])
        yOrigin = MAP_HEIGHT - gZoomViewCells[m_zoomLevel];
    if (xOrigin != m_viewX || yOrigin != m_viewY) {
        m_viewX = xOrigin;
        m_viewY = yOrigin;
        DrawRadar(true);
        DrawMap();
        UpdateMapView();
    }
}


void editManager::CheckScreenScroll(void) {
    i16 leftSide [[maybe_unused]];
    i16 bottomSide [[maybe_unused]];
    i16 rightSide [[maybe_unused]];
    i16 topSide [[maybe_unused]];

    leftSide = EDIT_SCROLL_BORDER;
    rightSide = LOGICAL_SCREEN_WIDTH - H2EnumIndex(EDIT_SCROLL_BORDER) - 1;
    topSide = EDIT_SCROLL_BORDER;
    bottomSide = LOGICAL_SCREEN_HEIGHT - H2EnumIndex(EDIT_SCROLL_BORDER);
    if (KBTickCount() - gLastScrollTime > EDIT_SCROLL_TICK_INTERVAL) {
        i32 mouseX;
        i32 mouseY;
        i32 oldMapY;
        i32 oldMapX;

        gLastScrollTime = KBTickCount();
        oldMapX = m_viewX;
        oldMapY = m_viewY;
        gpMouseManager->MouseCoords(mouseX, mouseY);
        if (mouseX >= 0 && mouseX < LOGICAL_SCREEN_WIDTH && mouseY >= 0 && mouseY < LOGICAL_SCREEN_HEIGHT) {
            if (mouseX < EDIT_SCROLL_BORDER) {
                if (mouseY < EDIT_SCROLL_BORDER)
                    ScreenScroll(MAP_DIRECTION_NORTH_WEST, 1);
                else if (mouseY > LOGICAL_SCREEN_HEIGHT - H2EnumIndex(EDIT_SCROLL_BORDER))
                    ScreenScroll(MAP_DIRECTION_SOUTH_WEST, 1);
                else
                    ScreenScroll(MAP_DIRECTION_WEST, 1);
            } else if (mouseX > LOGICAL_SCREEN_WIDTH - H2EnumIndex(EDIT_SCROLL_BORDER) - 1) {
                if (mouseY < EDIT_SCROLL_BORDER)
                    ScreenScroll(MAP_DIRECTION_NORTH_EAST, 1);
                else if (mouseY > LOGICAL_SCREEN_HEIGHT - H2EnumIndex(EDIT_SCROLL_BORDER))
                    ScreenScroll(MAP_DIRECTION_SOUTH_EAST, 1);
                else
                    ScreenScroll(MAP_DIRECTION_EAST, 1);
            } else if (mouseY < EDIT_SCROLL_BORDER) {
                ScreenScroll(MAP_DIRECTION_NORTH, 1);
            } else if (mouseY > LOGICAL_SCREEN_HEIGHT - H2EnumIndex(EDIT_SCROLL_BORDER)) {
                ScreenScroll(MAP_DIRECTION_SOUTH, 1);
            }
        }
        if (gpMouseManager->m_cursorFrame >= ADVENTURE_POINTER_SCROLL_FIRST
            && gpMouseManager->m_cursorFrame < ADVENTURE_POINTER_SCROLL_END && oldMapX == m_viewX
            && oldMapY == m_viewY)
            gpMouseManager->SetPointer(EDIT_POINTER_DEFAULT);
    }
}


void FillInOverlayTiles(void) {
    i32 nextFrame;
    i32 width;
    i32 typeFirstFrame;
    i32 curTileset;
    i32 i;
    i32 gx;
    i32 cellIndex;
    i32 gy;
    overlayType* shape;
    i32 baseFrame;

    curTileset = -1;
    baseFrame = 0;
    typeFirstFrame = 0;
    for (i = 0; i < OVERLAY_TYPE_COUNT; i++) {
        width = 0;
        shape = &gOverlayTypes[i];
        if (shape->tileset != curTileset)
            baseFrame = 0;
        curTileset = shape->tileset;
        if (shape->frameNumbering == OVERLAY_FRAMES_SHARED)
            baseFrame = typeFirstFrame;
        if (shape->frameNumbering == OVERLAY_FRAMES_OWN)
            baseFrame = 0;
        nextFrame = baseFrame;
        typeFirstFrame = baseFrame;
        cellIndex = 0;
        for (gy = 0; gy < OVERLAY_GRID_HEIGHT; gy++) {
            for (gx = 0; gx < OVERLAY_GRID_WIDTH; gx++) {
                if (OverlayGridHas(shape->occupiedRows, gx, gy)) {
                    if (OVERLAY_GRID_WIDTH - gx > width)
                        width = OVERLAY_GRID_WIDTH - gx;
                    if (shape->frameNumbering >= 0)
                        shape->frames[cellIndex] = nextFrame;
                    if (OverlayGridHas(shape->animatedRows, gx, gy)) {
                        nextFrame += shape->animationFrames + 1;
                        baseFrame += shape->animationFrames + 1;
                    } else {
                        nextFrame++;
                        baseFrame++;
                    }
                } else if (shape->frameNumbering >= 0) {
                    shape->frames[cellIndex] = OVERLAY_NO_FRAME;
                }
                cellIndex++;
            }
        }
        shape->width = width;
    }
}


b32 HasExtraObjectData(i32 triggerType) {
    return triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_CASTLE)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_TOWN)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_CASTLE)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_SIGN)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_SPHINX)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_BOTTLE)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_MAP_EVENT)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_HERO)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_JAIL);
}

b32 LocationHasSpecialDetails(i32 triggerType) {
    return triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_ULTIMATE_ARTIFACT)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_CASTLE)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_TOWN)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_CASTLE)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_SIGN)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_SPHINX)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_BOTTLE)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_MAP_EVENT)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_HERO)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_MONSTER)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_MONSTER)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_MONSTER_WEAK)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_MONSTER_MEDIUM)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_MONSTER_STRONG)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_MONSTER_VERY_STRONG)
        || triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_JAIL);
}


void DeleteExtraObjectData(u32 index) {
    i32 i;
    i32 j;
    i32 k;
    mapCell* cell;

    delete gEditManager->m_extras[index];
    if (index + 1 < static_cast<u32>(gEditManager->m_extraCount)) {
        memmove(
            &gEditManager->m_extras[index],
            &gEditManager->m_extras[index + 1],
            (gEditManager->m_extraCount - (index + 1)) * sizeof(gEditManager->m_extras[0])
        );
        memmove(
            &gEditManager->m_extraSizes[index],
            &gEditManager->m_extraSizes[index + 1],
            (gEditManager->m_extraCount - (index + 1)) * sizeof(gEditManager->m_extraSizes[0])
        );
    }
    gEditManager->m_extraCount--;
    for (k = 0; k < gEditMapHeader.rumourCount; k++) {
        if (gRumourExtras[k] >= index)
            gRumourExtras[k]--;
    }
    for (k = 0; k < gEditMapHeader.timeEventCount; k++) {
        if (gTimeEventExtras[k] >= index)
            gTimeEventExtras[k]--;
    }
    for (i = 0; i < MAP_WIDTH; i++) {
        for (j = 0; j < MAP_HEIGHT; j++) {
            cell = gMap.CellAt(i, j);
            if (HasExtraObjectData(cell->m_triggerType) && cell->m_objectMetadata >= index)
                cell->m_objectMetadata--;
        }
    }
}


void editManager::CoalesceObjectData(void) {
    i32 i;
    i32 j;
    i32 index;
    mapCell* cell;
    u8 usedExtras[EDIT_MANAGER_EXTRA_CAPACITY];

    memset(usedExtras, 0, sizeof(usedExtras));
    for (index = 0; index < gEditMapHeader.timeEventCount; index++)
        usedExtras[gTimeEventExtras[index]] = true;
    for (index = 0; index < gEditMapHeader.rumourCount; index++)
        usedExtras[gRumourExtras[index]] = true;
    for (i = 0; i < MAP_WIDTH; i++) {
        for (j = 0; j < MAP_HEIGHT; j++) {
            cell = gMap.CellAt(i, j);
            if (HasExtraObjectData(cell->m_triggerType))
                usedExtras[cell->m_objectMetadata] = true;
        }
    }
    for (index = m_extraCount - 1; index >= EDIT_MANAGER_FIRST_EXTRA; index--) {
        if (!usedExtras[index])
            DeleteExtraObjectData(index);
    }
    SaveUndo();
}

typedef enum EditTownNames {


    EDIT_TOWN_NAME_PREFIX_LENGTH = 4
} EditTownNames;

typedef enum EditPlayerFactions {


    EDIT_HERO_SPRITES_PER_PLAYER = 7,
    EDIT_PLAYER_FACTION_SLOTS    = 7
} EditPlayerFactions;


void CalculatePlayerNumbers(void) {
    i32 onlyFaction;
    i32 humanMin;
    i32 humanCount;
    i32 player;
    i32 cellFaction;
    i32 x;
    i32 i;
    i32 y;
    i32 k;
    i32 numPlayers;
    i32 nFactions;
    mapCell* cell;
    u8 factionSeen[GAME_PLAYER_COUNT][EDIT_PLAYER_FACTION_SLOTS];

    humanCount = 0;
    numPlayers = 0;
    humanMin = 0;
    for (i = 0; i < GAME_PLAYER_COUNT; i++) {
        if (!gEditMapHeader.playerEnabled[i]) {
            gEditMapHeader.playerCanHuman[i] = false;
            gEditMapHeader.playerCanComputer[i] = false;
        } else {
            if (!gEditMapHeader.playerCanHuman[i] && !gEditMapHeader.playerCanComputer[i])
                gEditMapHeader.playerCanComputer[i] = true;
            if (gEditMapHeader.playerCanHuman[i])
                humanCount++;
            if (gEditMapHeader.playerCanHuman[i] || gEditMapHeader.playerCanComputer[i])
                numPlayers++;
            if (gEditMapHeader.playerCanHuman[i] && !gEditMapHeader.playerCanComputer[i])
                humanMin++;
        }
    }
    if (!humanCount) {
        for (i = 0; i < GAME_PLAYER_COUNT; i++) {
            if (gEditMapHeader.playerEnabled[i]) {
                gEditMapHeader.playerCanHuman[i] = true;
                humanCount = 1;
                humanMin = 1;
                break;
            }
        }
    }
    gEditMapHeader.playerCount = numPlayers;
    gEditMapHeader.minHumanPlayers = humanMin;
    gEditMapHeader.maxHumanPlayers = humanCount;
    for (i = 0; i < GAME_PLAYER_COUNT; i++)
        gEditMapHeader.playerRace[i] = FACTION_NONE;
    memset(factionSeen, 0, sizeof(factionSeen));
    for (x = 0; x < MAP_WIDTH; x++) {
        for (y = 0; y < MAP_HEIGHT; y++) {
            cell = gMap.CellAt(x, y);
            if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_HERO)) {
                player = cell->m_objectIndex / EDIT_HERO_SPRITES_PER_PLAYER;
                cellFaction = cell->m_objectIndex % EDIT_HERO_SPRITES_PER_PLAYER;
                factionSeen[player][cellFaction] = true;
            }
            if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_CASTLE)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_TOWN)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_CASTLE)) {
                TownExtra* town;

                town = static_cast<TownExtra*>(gEditManager->m_extras[cell->m_objectMetadata]);
                if (town->owner != TOWN_OWNER_NONE) {
                    player = town->owner;
                    cellFaction = H2EnumIndex(town->faction);
                    factionSeen[player][cellFaction] = true;
                }
            }
        }
    }
    onlyFaction = 0;
    for (i = 0; i < GAME_PLAYER_COUNT; i++) {
        if (!gEditMapHeader.playerEnabled[i])
            continue;
        if (factionSeen[i][H2EnumIndex(FACTION_NEUTRAL)]) {
            gEditMapHeader.playerRace[i] = FACTION_RANDOM;
        } else {
            nFactions = 0;
            for (k = 0; k < H2EnumIndex(FACTION_COUNT); k++) {
                if (factionSeen[i][k]) {
                    nFactions++;
                    onlyFaction = k;
                }
            }
            if (nFactions == 1)
                gEditMapHeader.playerRace[i] = static_cast<FactionType>(onlyFaction);
            else
                gEditMapHeader.playerRace[i] = FACTION_NEUTRAL;
        }
    }
}


void ResetPlayerAvailability(void) {
    i32 unusedIndex [[maybe_unused]];
    i32 i;
    i32 j;
    mapCell* cell;

    memset(gEditMapHeader.playerEnabled, 0, sizeof(gEditMapHeader.playerEnabled));
    for (i = 0; i < MAP_WIDTH; i++) {
        for (j = 0; j < MAP_HEIGHT; j++) {
            cell = gMap.CellAt(i, j);
            if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_HERO))
                gEditMapHeader.playerEnabled[cell->m_objectIndex / EDIT_HERO_SPRITES_PER_PLAYER] = true;
            if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_CASTLE)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_TOWN)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_CASTLE)) {
                TownExtra* town;

                town = static_cast<TownExtra*>(gEditManager->m_extras[cell->m_objectMetadata]);
                if (town->owner != TOWN_OWNER_NONE)
                    gEditMapHeader.playerEnabled[town->owner] = true;
            }
        }
    }
    CalculatePlayerNumbers();
}


void editManager::RandomizeTownNames(void) {
    i32 unusedA [[maybe_unused]];
    i32 unusedB [[maybe_unused]];
    i32 choice;
    i32 i;
    i32 j;
    TownExtra* townExtra;
    u8 namesTaken[EDITOR_TOWN_NAME_COUNT];
    mapCell* cell;

    memset(namesTaken, 0, sizeof(namesTaken));
    for (i = 0; i < MAP_WIDTH; i++) {
        for (j = 0; j < MAP_HEIGHT; j++) {
            cell = gMap.CellAt(i, j);
            if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_CASTLE)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_TOWN)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_CASTLE)) {
                townExtra = static_cast<TownExtra*>(gEditManager->m_extras[cell->m_objectMetadata]);
                for (choice = 0; choice < EDITOR_TOWN_NAME_COUNT; choice++) {
                    if (!strcmp(townExtra->name, gTownNames[choice])
                        || !strnicmp(townExtra->name, "dusk", EDIT_TOWN_NAME_PREFIX_LENGTH)
                        || !strnicmp(townExtra->name, "necr", EDIT_TOWN_NAME_PREFIX_LENGTH)) {
                        if (!strnicmp(townExtra->name, "dusk", EDIT_TOWN_NAME_PREFIX_LENGTH)
                            || !strnicmp(townExtra->name, "necr", EDIT_TOWN_NAME_PREFIX_LENGTH))
                            namesTaken[choice] = true;
                        if (namesTaken[choice]) {
                            while (namesTaken[choice])
                                choice = Random(0, EDITOR_TOWN_NAME_COUNT - 1);
                            strcpy(townExtra->name, gTownNames[choice]);
                        }
                        namesTaken[choice] = true;
                        break;
                    }
                }
            }
        }
    }
}


b32 editManager::FindArtifact(i32 index, i32* x, i32* y) {
    i32 count;
    i32 i;
    i32 j;
    mapCell* cell;

    count = 0;
    for (j = 0; j < MAP_HEIGHT; j++) {
        for (i = 0; i < MAP_WIDTH; i++) {
            cell = gMap.CellAt(i, j);
            if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_ARTIFACT)) {
                if (count == index) {
                    *x = i;
                    *y = j;
                    return true;
                }
                count++;
            }
        }
    }
    *x = *y = -1;
    return false;
}

b32 editManager::FindTown(i32 index, i32* x, i32* y) {
    i32 i;
    i32 j;
    mapCell* cell;
    i32 numTowns;

    numTowns = 0;
    for (j = 0; j < MAP_HEIGHT; j++) {
        for (i = 0; i < MAP_WIDTH; i++) {
            cell = gMap.CellAt(i, j);
            if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_TOWN)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_RANDOM_CASTLE)
                || cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_CASTLE)) {
                if (numTowns == index) {
                    *x = i;
                    *y = j;
                    return true;
                }
                numTowns++;
            }
        }
    }
    *x = *y = -1;
    return false;
}

b32 editManager::FindHero(i32 index, i32* x, i32* y) {
    i32 i;
    i32 j;
    i32 heroOrdinal;
    mapCell* cell;

    heroOrdinal = 0;
    for (j = 0; j < MAP_HEIGHT; j++) {
        for (i = 0; i < MAP_WIDTH; i++) {
            cell = gMap.CellAt(i, j);
            if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_HERO)) {
                if (heroOrdinal == index) {
                    *x = i;
                    *y = j;
                    return true;
                }
                heroOrdinal++;
            }
        }
    }
    *x = *y = -1;
    return false;
}


i32 FileOptions(void) {
    i32 result;
    heroWindow* window;
    tag_message message [[maybe_unused]];

    window = new heroWindow(EDIT_FILE_MENU_X, EDIT_FILE_MENU_Y, "ecpanel.bin");
    if (window == NULL)
        MemError();
    gpWindowManager->DoDialog(window, FileOptionsHandler, 0);
    delete window;
    result = EDIT_FILE_MENU_NONE;
    switch (gpWindowManager->m_dialogResult) {
        case EDIT_FILE_MENU_NEW:
        case EDIT_FILE_MENU_LOAD:
        case EDIT_FILE_MENU_QUIT:
        case EDIT_FILE_MENU_SAVE:
            result = gpWindowManager->m_dialogResult;
            break;
    }
    return result;
}


MessageDispatchResult FileOptionsHandler(struct tag_message& message) {
    b32 done;
    char text[EDIT_MENU_QUESTION_SIZE];

    done = false;
    if (message.type == MESSAGE_WIDGET) {
        if ((H2EnumIndex((message.payload.widget.modifiers) & (MESSAGE_MODIFIER_RIGHT_BUTTON)))) {
            if (IS_WIDGET_SELECTION_NOTIFICATION(message.payload.widget.command)) {
                i32 helpIndex;

                helpIndex = EDIT_FILE_MENU_HELP_NONE;
                switch (message.payload.widget.id) {
                    case EDIT_FILE_MENU_NEW:
                        helpIndex = EDIT_FILE_MENU_HELP_NEW;
                        break;
                    case EDIT_FILE_MENU_LOAD:
                        helpIndex = EDIT_FILE_MENU_HELP_LOAD;
                        break;
                    case EDIT_FILE_MENU_SAVE:
                        helpIndex = EDIT_FILE_MENU_HELP_SAVE;
                        break;
                    case EDIT_FILE_MENU_QUIT:
                        helpIndex = EDIT_FILE_MENU_HELP_QUIT;
                        break;
                    case EDIT_FILE_MENU_CLOSE:
                        helpIndex = EDIT_FILE_MENU_HELP_CLOSE;
                        break;
                }
                if (helpIndex >= 0)
                    NormalDialog(gFileMenuHelp[helpIndex], EDIT_MENU_HELP_DIALOG);
            }
        } else {
            switch (message.payload.widget.command) {
                case WIDGET_NOTIFY_DESELECT:
                    switch (message.payload.widget.id) {
                        case EDIT_FILE_MENU_NEW:
                            strcpy(text, localization::Tr("editor.file.confirm_new"));
                            goto confirm;
                        case EDIT_FILE_MENU_LOAD:
                            strcpy(text, localization::Tr("editor.file.confirm_load"));
                            goto confirm;
                        case EDIT_FILE_MENU_QUIT:
                            strcpy(text, localization::Tr("editor.file.confirm_quit"));
                        confirm:
                            done = true;
                            NormalDialog(text, NORMAL_DIALOG_CONFIRM);
                            if (gpWindowManager->m_dialogResult == NORMAL_DIALOG_NO)
                                done = false;
                            break;
                        case EDIT_FILE_MENU_SAVE:
                        case EDIT_FILE_MENU_CLOSE:
                            done = true;
                            break;
                    }
                    break;
            }
        }
    }
    if (done) {
        FINISH_DIALOG_MESSAGE(message);
        return MESSAGE_DISPATCH_FORWARD;
    }
    return MESSAGE_DISPATCH_CONSUME;
}

typedef enum EditSystemOptions {


    EDIT_OPTIONS_X                    = 160,
    EDIT_OPTIONS_Y                    = 33,
    EDIT_OPTIONS_ANIMATION_BUTTON     = 10,
    EDIT_OPTIONS_CYCLING_BUTTON       = 11,
    EDIT_OPTIONS_OBJECT_BOXES_BUTTON  = 13,
    EDIT_OPTIONS_COLOR_MICE_BUTTON    = 14,
    EDIT_OPTIONS_ANIMATION_TEXT       = 20,
    EDIT_OPTIONS_CYCLING_TEXT         = 21,
    EDIT_OPTIONS_OBJECT_BOXES_TEXT    = 23,
    EDIT_OPTIONS_COLOR_MICE_TEXT      = 24,
    EDIT_OPTIONS_ANIMATION_FRAMES     = 0,
    EDIT_OPTIONS_CYCLING_FRAMES       = 2,
    EDIT_OPTIONS_OBJECT_BOXES_FRAMES  = 4,
    EDIT_OPTIONS_COLOR_MICE_FRAMES    = 6,
    EDIT_OPTIONS_CLOSE                = DIALOG_BUTTON_0,
    EDIT_OPTIONS_HELP_NONE            = -1,
    EDIT_OPTIONS_HELP_CLOSE           = 0,
    EDIT_OPTIONS_HELP_ANIMATION       = 1,
    EDIT_OPTIONS_HELP_CYCLING         = 2,
    EDIT_OPTIONS_HELP_OBJECT_BOXES    = 3,
    EDIT_OPTIONS_HELP_COLOR_MICE      = 4
} EditSystemOptions;


heroWindow* gSystemOptionsWindow;
b32 gPrefsChanged;

void editManager::SystemOptions(void) {
    tag_message message [[maybe_unused]];

    gPrefsChanged = false;
    gSystemOptionsWindow = new heroWindow(EDIT_OPTIONS_X, EDIT_OPTIONS_Y, "espanel.bin");
    if (!gSystemOptionsWindow)
        MemError();
    SetWinText(gSystemOptionsWindow, EDITOR_WIN_TEXT_SYSTEM_OPTIONS);
    UpdateEditorSystemOptions(true);
    gpWindowManager->DoDialog(gSystemOptionsWindow, EditorSystemOptionsHandler, 0);
    delete gSystemOptionsWindow;
    if (gPrefsChanged)
        WritePrefs();
}

void UpdateEditorSystemOptions(b32 initialDraw) {
    tag_message message;

    SET_WIDGET_MESSAGE(message, WIDGET_COMMAND_SET_FRAME, EDIT_OPTIONS_ANIMATION_BUTTON);
    message.payload.widget.data.value = gConfig.editorScreenAnimation + EDIT_OPTIONS_ANIMATION_FRAMES;
    gSystemOptionsWindow->BroadcastMessage(message);
    message.payload.widget.id = EDIT_OPTIONS_CYCLING_BUTTON;
    message.payload.widget.data.value = gConfig.editorPaletteCycling + EDIT_OPTIONS_CYCLING_FRAMES;
    gSystemOptionsWindow->BroadcastMessage(message);
    message.payload.widget.id = EDIT_OPTIONS_OBJECT_BOXES_BUTTON;
    message.payload.widget.data.value = gConfig.showObjectBoxes + EDIT_OPTIONS_OBJECT_BOXES_FRAMES;
    gSystemOptionsWindow->BroadcastMessage(message);
    message.payload.widget.id = EDIT_OPTIONS_COLOR_MICE_BUTTON;
    message.payload.widget.data.value
        = CURRENT_GRAPHICS_CONFIG.colorMouseCursor + EDIT_OPTIONS_COLOR_MICE_FRAMES;
    gSystemOptionsWindow->BroadcastMessage(message);
    message.payload.widget.command = WIDGET_COMMAND_SET_TEXT;
    message.payload.widget.id = EDIT_OPTIONS_ANIMATION_TEXT;
    message.payload.widget.data.text = onOffText[gConfig.editorScreenAnimation];
    gSystemOptionsWindow->BroadcastMessage(message);
    message.payload.widget.id = EDIT_OPTIONS_CYCLING_TEXT;
    message.payload.widget.data.text = onOffText[gConfig.editorPaletteCycling];
    gSystemOptionsWindow->BroadcastMessage(message);
    message.payload.widget.id = EDIT_OPTIONS_OBJECT_BOXES_TEXT;
    message.payload.widget.data.text = onOffText[gConfig.showObjectBoxes];
    gSystemOptionsWindow->BroadcastMessage(message);
    message.payload.widget.id = EDIT_OPTIONS_COLOR_MICE_TEXT;
    message.payload.widget.data.text = onOffText[CURRENT_GRAPHICS_CONFIG.colorMouseCursor];
    gSystemOptionsWindow->BroadcastMessage(message);
    if (!initialDraw)
        gSystemOptionsWindow->DrawWindow(WINDOW_DRAW_UPDATE_SCREEN, 0, WINDOW_DRAW_ID_LIMIT);
}

MessageDispatchResult EditorSystemOptionsHandler(struct tag_message& message) {
    b32 redraw = false;
    b32 done = false;

    if (message.type == MESSAGE_WIDGET) {
        if ((H2EnumIndex((message.payload.widget.modifiers) & (MESSAGE_MODIFIER_RIGHT_BUTTON)))) {
            if (IS_WIDGET_SELECTION_NOTIFICATION(message.payload.widget.command)) {
                i32 helpIndex = EDIT_OPTIONS_HELP_NONE;
                switch (message.payload.widget.id) {
                    case EDIT_OPTIONS_CLOSE:
                        helpIndex = EDIT_OPTIONS_HELP_CLOSE;
                        break;
                    case EDIT_OPTIONS_ANIMATION_BUTTON:
                        helpIndex = EDIT_OPTIONS_HELP_ANIMATION;
                        break;
                    case EDIT_OPTIONS_CYCLING_BUTTON:
                        helpIndex = EDIT_OPTIONS_HELP_CYCLING;
                        break;
                    case EDIT_OPTIONS_OBJECT_BOXES_BUTTON:
                        helpIndex = EDIT_OPTIONS_HELP_OBJECT_BOXES;
                        break;
                    case EDIT_OPTIONS_COLOR_MICE_BUTTON:
                        helpIndex = EDIT_OPTIONS_HELP_COLOR_MICE;
                        break;
                }
                if (helpIndex >= 0)
                    NormalDialog(gSystemOptionsHelp[helpIndex], EDIT_MENU_HELP_DIALOG);
            }
        } else {
            switch (message.payload.widget.command) {
                case WIDGET_NOTIFY_DESELECT:
                    switch (message.payload.widget.id) {
                        case EDIT_OPTIONS_CLOSE:
                            done = true;
                            break;
                    }
                    break;
                case WIDGET_NOTIFY_SELECT:
                    switch (message.payload.widget.id) {
                        case EDIT_OPTIONS_ANIMATION_BUTTON:
                            gConfig.editorScreenAnimation = 1 - gConfig.editorScreenAnimation;
                            redraw = true;
                            gPrefsChanged = true;
                            break;
                        case EDIT_OPTIONS_CYCLING_BUTTON:
                            gConfig.editorPaletteCycling = 1 - gConfig.editorPaletteCycling;
                            gpWindowManager->m_updateFlags = gConfig.editorPaletteCycling;
                            redraw = true;
                            gPrefsChanged = true;
                            break;
                        case EDIT_OPTIONS_OBJECT_BOXES_BUTTON:
                            gConfig.showObjectBoxes = 1 - gConfig.showObjectBoxes;
                            redraw = true;
                            gPrefsChanged = true;
                            break;
                        case EDIT_OPTIONS_COLOR_MICE_BUTTON:
                            CURRENT_GRAPHICS_CONFIG.colorMouseCursor
                                = 1 - CURRENT_GRAPHICS_CONFIG.colorMouseCursor;
                            redraw = true;
                            gPrefsChanged = true;
                            gpMouseManager->SetColorMice(CURRENT_GRAPHICS_CONFIG.colorMouseCursor);
                            break;
                    }
                    break;
            }
        }
    }
    if (redraw)
        UpdateEditorSystemOptions(false);
    if (done) {
        FINISH_DIALOG_MESSAGE(message);
        return MESSAGE_DISPATCH_FORWARD;
    }
    return MESSAGE_DISPATCH_CONSUME;
}


void editManager::ToggleGroundVariant(void) {
    i32 terrain;
    i32 x;
    i32 y;
    b32 vary;
    i32 ground;

    SaveUndo();
    gpMouseManager->MouseCoords(x, y);
    ScreenToCell(x, y);
    x += m_viewX;
    y += m_viewY;
    ground = gMap.CellAt(x, y)->m_terrainImageIndex;
    terrain = H2EnumIndex(giGroundToTerrain[ground]);
    if (giGroundShape[ground] & GROUND_SHAPE_VARIED)
        vary = false;
    else
        vary = true;
    gMap.CellAt(x, y)->m_terrainImageIndex = ChooseGroundTile(
        terrain, giGroundShape[ground] & EDIT_SHAPE_MASK, true, x, y, vary,
        static_cast<float>(vary != false)
    );
    DrawMap();
    UpdateMapView();
}

typedef enum EditGroundVariety {

    EDIT_GROUND_VARIETY_LEVELS = 10
} EditGroundVariety;

void editManager::RandomizeGround(i32 variety) {
    i32 terrain;
    i32 groundTile;
    b32 isEmpty;
    i32 x;
    i32 y;
    float chances[EDIT_GROUND_VARIETY_LEVELS];

    SaveUndo();
    chances[0] = 0.0f;
    chances[1] = 0.2f;
    chances[2] = 0.4f;
    chances[3] = 0.6f;
    chances[4] = 0.8f;
    chances[5] = 1.0f;
    chances[6] = 1.3f;
    chances[7] = 1.6f;
    chances[8] = 2.0f;
    chances[9] = 2.4f;
    for (x = 0; x < MAP_WIDTH; x++) {
        for (y = 0; y < MAP_HEIGHT; y++) {
            groundTile = gMap.CellAt(x, y)->m_terrainImageIndex;
            terrain = H2EnumIndex(giGroundToTerrain[groundTile]);
            if (gMap.CellAt(x, y)->m_objectIndex == MAPCELL_SPRITE_NONE
                && gMap.CellAt(x, y)->m_overlayIndex == MAPCELL_SPRITE_NONE)
                isEmpty = true;
            else
                isEmpty = false;
            if (!variety)
                isEmpty = false;
            gMap.CellAt(x, y)->m_terrainImageIndex = ChooseGroundTile(
                terrain, giGroundShape[groundTile] & EDIT_SHAPE_MASK, true, x, y, false,
                isEmpty ? chances[variety] : 0.0f
            );
        }
    }
    DrawMap();
    UpdateMapView();
}


b8 UsesExpansionObjects(void) {
    i32 i;
    i32 j;
    i32 k;
    mapCell* cell;

    for (j = 0; j < MAP_HEIGHT; j++) {
        for (i = 0; i < MAP_WIDTH; i++) {
            cell = gMap.CellAt(i, j);
            switch (cell->m_triggerType & MAP_TRIGGER_TYPE_MASK) {
                case MAP_OBJECT_BARRIER:
                case MAP_OBJECT_TRAVELER_TENT:
                case MAP_OBJECT_EXPANSION_DWELLING:
                case MAP_OBJECT_EXPANSION_OBJECT:
                case MAP_OBJECT_JAIL:
                    return true;
                case MAP_OBJECT_ARTIFACT:
                    if (cell->m_objectIndex >> 1 > H2EnumIndex(ARTIFACT_MAGIC_BOOK))
                        return true;
                    break;
                case MAP_OBJECT_HERO:
                    if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_HERO) && cell->m_objectMetadata) {
                        HeroExtra* hero;

                        hero = static_cast<HeroExtra*>(gEditManager->m_extras[cell->m_objectMetadata]);
                        for (k = 0; k < EVENT_RECORD_HERO_ARTIFACT_COUNT; k++) {
                            if (hero->artifacts[k] > H2EnumIndex(ARTIFACT_MAGIC_BOOK))
                                return true;
                        }
                    }
                    break;
                case MAP_OBJECT_SPHINX:
                    if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_SPHINX) && cell->m_objectMetadata) {
                        mapEventExtra* sphinx;

                        sphinx = static_cast<mapEventExtra*>(gEditManager->m_extras[cell->m_objectMetadata]);
                        if (sphinx->artifact > H2EnumIndex(ARTIFACT_MAGIC_BOOK))
                            return true;
                    }
                    break;
                case MAP_OBJECT_MAP_EVENT:
                    if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_MAP_EVENT) && cell->m_objectMetadata) {
                        EventExtra* event;

                        event = static_cast<EventExtra*>(gEditManager->m_extras[cell->m_objectMetadata]);
                        if (event->artifact > H2EnumIndex(ARTIFACT_MAGIC_BOOK))
                            return true;
                    }
                    break;
                case MAP_OBJECT_CASTLE:
                    if (cell->m_triggerType == MAP_ACTION_TRIGGER(MAP_OBJECT_CASTLE) && cell->m_objectMetadata) {
                        TownExtra* town;

                        town = static_cast<TownExtra*>(gEditManager->m_extras[cell->m_objectMetadata]);
                        if (town->faction == FACTION_NECROMANCER && town->hasCustomBuildings
                            && (town->buildings & (1 << H2EnumIndex(BUILDING_SLOT_NECROMANCER_SHRINE))))
                            return true;
                    }
                    break;
            }
        }
    }
    return false;
}
